EmailUrlInfo
//This regex identifies emails containing the "T-Dot" redirector pattern in the URL
| where Url matches regex @"s?\:\/\/(?:www\.)?t\.(?:[\w\-\.]+\/+)+(?:r|redirect)\/?\?" 
    //This regex narrows in on emails that contain the known malicious domain pattern in the URL from the most recent campaigns
    and Url matches regex @"[a-zA-Z]\-[a-zA-Z]{2}\.(xyz|club|shop)"

let gran = 1d;
let minTime = startofday(ago(30d));
let maxTime = startofday(now());
let agg = materialize(EmailPostDeliveryEvents
    | where Timestamp >= minTime and Timestamp < maxTime
    | where ActionTrigger has "AdminAction"
    | summarize ["Soft Delete"] = countif(Action has 'Soft Delete'), ["Hard Delete"] = countif(Action has 'Hard Delete'), ["Moved to junk folder"] = countif(Action has 'Moved to junk folder'), ["Moved to inbox"] = countif(Action has 'Moved to inbox'), ["Quarantine release"] = countif(Action has 'Quarantine release') by Timestamp = bin(Timestamp, gran));
range Timestamp from minTime to maxTime - 1d step gran
| join kind=leftouter (agg) on Timestamp
| project Timestamp, ["Soft Delete"] = coalesce(["Soft Delete"], 0), ["Hard Delete"] = coalesce(["Hard Delete"], 0), ["Moved to junk folder"] = coalesce(["Moved to junk folder"], 0), ["Moved to inbox"] = coalesce(["Moved to inbox"], 0), ["Quarantine release"] = coalesce(["Quarantine release"], 0)
| sort by Timestamp asc
| render timechart

//Find possible download and execution using Msiexec
DeviceProcessEvents
| where TimeGenerated > ago(7d)
//MSIExec
| where FileName =~ "msiexec.exe" and 
//With domain in command line
(ProcessCommandLine has "http" and ProcessCommandLine has "return")//Find PowerShell running files from the temp folder

DeviceProcessEvents
// Pro-tip: 
// There are many different ways to run a process from a file - e.g. by using full path, env. variables, ~1 annotation, more...
// So, to find executions of a known filename, better filter on the filename (and possibly on folder path) than on the commandline.
| where FileName in~ ("net.exe", "net1.exe") and TimeGenerated > ago(3d)
// Parse the user name from the commandline.
// To have case-insensitive parsing use the i flag, to have non-greedy match (e.g. CreatedUser as short as possible), specify U flag:
// "kind=regex flags=i"
| parse kind=regex flags=iU ProcessCommandLine with * "user " CreatedUser " " * "/ad"
// Filter rows where user could not be parsed - e.g. because it was not a user command, or the /add commandline switch was not specified.
| where isnotempty(CreatedUser)
// Every net.exe executed will run net1.exe with the same commandline.
// in this where clause we remove such rows, as they duplicate the number of results we have without adding any value.
| where not (FileName =~ "net1.exe" and InitiatingProcessFileName =~ "net.exe" and replace("net", "net1", InitiatingProcessCommandLine) =~ ProcessCommandLine)
// If /domain is specified, so the user is created on the domain controller.
// Also, any prefix that's longer than 1 char will also do the same, e.g. /do, /dom, /doma, ....
| extend CreatedOnLocalMachine=(ProcessCommandLine !contains "/do")
| where ProcessCommandLine !contains "/add" or (CreatedOnLocalMachine == 0 and ProcessCommandLine !contains "/domain")
| summarize MachineCount=dcount(DeviceName) by CreatedUser, CreatedOnLocalMachine, InitiatingProcessFileName, FileName, ProcessCommandLine, InitiatingProcessCommandLine

let ADAZUsers =  IdentityInfo 
