**The users most targeted by inbound email threats across all threat types (malware, phishing, and spam) in the selected period. Concentrated targeting of a few individuals is a strong signal of deliberate campaigns.**<br><br>**Recommended action:** Prioritise these users for security awareness training, tighter protection policies (for example the Strict preset), and closer monitoring - they are your highest-risk people."},"name":"exec vap banner","id":"1fe431fb-cc96-4e81-b164-3a1a3823ebeb"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query surfaces the users most targeted by inbound email threats across all threat types (malware, phishing, spam) for the selected period, so SecOps can prioritise the highest-risk individuals. Similar to a "Most Attacked People" view.
EmailEvents
| where EmailDirection == "Inbound"
| where isnotempty(ThreatTypes)
| summarize
    ['Total Threats'] = count(),
    Malware = countif(ThreatTypes has "Malware"),
    Phish   = countif(ThreatTypes has "Phish"),
    Spam    = countif(ThreatTypes has "Spam"),
    ['Last Seen'] = max(Timestamp)
    by ['User']=RecipientEmailAddress
| top 10 by ['Total Threats']
| project ['User'], ['Total Threats'], Malware, Phish, Spam, ['Last Seen']","size":3,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"table","gridSettings":{"filter":true,"formatters":[{"columnMatch":"Malware","formatter":3,"formatOptions":{"palette":"blue","customColumnWidthSetting":"145px"},"numberFormat":{"unit":17,"options":{"style":"decimal","maximumFractionDigits":1}}},{"columnMatch":"Phish","formatter":3,"formatOptions":{"palette":"blue","customColumnWidthSetting":"145px"},"numberFormat":{"unit":17,"options":{"style":"decimal","maximumFractionDigits":1}}},{"columnMatch":"Spam","formatter":3,"formatOptions":{"palette":"blue","customColumnWidthSetting":"145px"},"numberFormat":{"unit":17,"options":{"style":"decimal","maximumFractionDigits":1}}},{"columnMatch":"Total Threats","formatter":3,"formatOptions":{"palette":"blue","customColumnWidthSetting":"145px"},"numberFormat":{"unit":17,"options":{"style":"decimal","maximumFractionDigits":1}}}]}},"customWidth":"100","name":"exec vap table","styleSettings":{"margin":"10px","padding":"10px"},"id":"2dfd91b1-b8d3-4a72-aaf4-a30a1886bed7"},{"type":1,"content":{"json":"## Detection trend over time - grouped by {Granularity}
**Represents total emails, total detections, total user submissions and admin email submissions over time summarizing the data per {Granularity} interval**"},"name":"text - 14","id":"ddbbdaef-b374-42a8-821c-7fcd7ee53ba9"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query visualises total emails, total detections, total user, and admin email submissions over time summarizing the data daily
let gran = {Granularity};
let minTime = toscalar(EmailEvents | summarize min(Timestamp));
let maxTime = toscalar(EmailEvents | summarize max(Timestamp));
let scaffold = range Timestamp from bin(minTime, gran) to bin(maxTime, gran) step gran;
let baseQuery = materialize(EmailEvents
| extend Key = strcat(NetworkMessageId , "-", RecipientEmailAddress)
| summarize arg_max(Timestamp, *) by Key
| where isnotempty(Timestamp));
let sub = materialize(CloudAppEvents
| extend Record = (parse_json(RawEventData)).RecordType, SubmissionContentType = tostring((parse_json(RawEventData)).SubmissionContentType)
| where Record == 29);
let zapbase = EmailPostDeliveryEvents
| extend Key = strcat(NetworkMessageId , "-", RecipientEmailAddress)
| summarize arg_max(Timestamp, *) by Key
| where ActionResult == "Success"
| where ActionType == "Phish ZAP" or ActionType == "Malware ZAP" or ActionType == "Spam ZAP";
union
(scaffold | join kind=leftouter (baseQuery | where EmailDirection == "Inbound" | summarize Count = count() by Timestamp = bin(Timestamp, gran)) on Timestamp | project Timestamp, Count = coalesce(Count, 0), Details = "Total Inbound Emails"),
(scaffold | join kind=leftouter (baseQuery | where ThreatTypes has ('Phish') | summarize Count = count() by Timestamp = bin(Timestamp, gran)) on Timestamp | project Timestamp, Count = coalesce(Count, 0), Details = "Emails Detected as Phish"),
(scaffold | join kind=leftouter (baseQuery | where ThreatTypes has ('Malware') | summarize Count = count() by Timestamp = bin(Timestamp, gran)) on Timestamp | project Timestamp, Count = coalesce(Count, 0), Details = "Emails Detected as Malware"),
(scaffold | join kind=leftouter (baseQuery | where ThreatTypes has ('Spam') | summarize Count = count() by Timestamp = bin(Timestamp, gran)) on Timestamp | project Timestamp, Count = coalesce(Count, 0), Details = "Emails Detected as Spam"),
(scaffold | join kind=leftouter (baseQuery | where EmailDirection == "Intra-org" | summarize Count = count() by Timestamp = bin(Timestamp, gran)) on Timestamp | project Timestamp, Count = coalesce(Count, 0), Details = "Total Intra-org Emails"),
(scaffold | join kind=leftouter (baseQuery | where EmailDirection == "Outbound" | summarize Count = count() by Timestamp = bin(Timestamp, gran)) on Timestamp | project Timestamp, Count = coalesce(Count, 0), Details = "Total Outbound Emails"),
(scaffold | join kind=leftouter (baseQuery | where isnotempty(ThreatTypes) | summarize Count = count() by Timestamp = bin(Timestamp, gran)) on Timestamp | project Timestamp, Count = coalesce(Count, 0), Details = "Total Emails with Threat"),
(scaffold | join kind=leftouter (sub | where ActionType == "UserSubmission" | summarize Count = count() by Timestamp = bin(Timestamp, gran)) on Timestamp | project Timestamp, Count = coalesce(Count, 0), Details = "Total Emails Reported by Users"),
(scaffold | join kind=leftouter (zapbase | summarize Count = count() by Timestamp = bin(Timestamp, gran)) on Timestamp | project Timestamp, Count = coalesce(Count, 0), Details = "Total Emails Removed by ZAP"),
(scaffold | join kind=leftouter (sub | where ActionType == "AdminSubmissionSubmitted" and SubmissionContentType == "Mail" | summarize Count = count() by Timestamp = bin(Timestamp, gran)) on Timestamp | project Timestamp, Count = coalesce(Count, 0), Details = "Total Emails Reported by Admins")","size":0,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"linechart","chartSettings":{"xAxis":"Timestamp","seriesLabelSettings":[{"seriesName":"Total Inbound Emails","label":"Inbound Emails","color":"green"},{"seriesName":"Total Emails with Threat","label":"Emails with Threat","color":"redDark"},{"seriesName":"Emails Detected as Phish","label":"Emails with Phish","color":"redBright"},{"seriesName":"Emails Detected as Malware","label":"Emails with Malware","color":"red"},{"seriesName":"Total Intra-org Emails","label":"Intra-org Emails","color":"greenDark"},{"seriesName":"Emails Detected as Spam","label":"Emails with Spam","color":"gray"},{"seriesName":"Total Outbound Emails","label":"Outbound Emails","color":"greenDarkDark"},{"seriesName":"Total Emails Removed by ZAP","label":"Emails ZAP-d","color":"orangeDark"},{"seriesName":"Total Emails Reported by Users","label":"User Reported Emails","color":"lightBlue"},{"seriesName":"Total Emails Reported by Admins","color":"blueDark"}]}},"customWidth":"100","name":"query - 1","styleSettings":{"margin":"10px","padding":"10px"},"id":"bcbefa48-f553-4290-acff-2691caf898ea"},{"type":1,"content":{"json":"## Bad traffic (%) - Inbound Emails - grouped by {Granularity}
