| sort by Details asc, Timestamp asc","size":0,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"linechart","chartSettings":{"createOtherGroup":15}},"customWidth":"100","conditionalVisibility":{"parameterName":"Tab","comparison":"isEqualTo","value":"3"},"name":"query - Phish DetTech Trend","styleSettings":{"margin":"10px","padding":"10px"},"id":"b0b16329-e1a6-4138-871e-76d57a60b978"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query visualises total emails with Phish detections summarized by individual Phish detection technology/control in Microsoft Defender for Office 365.
//Each detection technology is counted individually via mv-expand over DetectionMethods.Phish (matching the sibling trend line chart), so a message flagged by multiple techniques counts once per technique.
//The where clause excludes deliveries to the SecOps Mailbox and by the Phish Simulation system.
EmailEvents 
