| where DetectionMethods has "Phish"
| mv-expand Details = parse_json(DetectionMethods).Phish to typeof(string)
| where isnotempty(Details)
| summarize Count = count() by Details
| sort by Count desc
| project ['Detection Technology'] = Details, ['Detections'] = Count","size":3,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"table","gridSettings":{"formatters":[{"columnMatch":"Detections","formatter":3,"formatOptions":{"palette":"redDark","customColumnWidthSetting":"30ch"},"numberFormat":{"unit":17,"options":{"style":"decimal","maximumFractionDigits":1}}}],"filter":true}},"customWidth":"100","conditionalVisibility":{"parameterName":"Tab","comparison":"isEqualTo","value":"3"},"name":"query - Phish DetTech Pie","styleSettings":{"margin":"10px","padding":"10px"},"id":"5270ba04-599f-4940-805b-687f7475bc70"},{"type":1,"content":{"json":"### Phish Detections by SenderIPv4 Geo Location<br>

**Visualizes the email sending infrastructure sender IPv4 addresses associated with inbound emails detected as Phish, along with the IPv4 address geographic coordinates (latitude, longitude) and country information. Helps identify high-risk regions and sources for targeted threat mitigation.**"},"name":"text - Phish Geo Header","id":"ddd0c12f-1bb1-4d7d-afb4-f28bcfcd7c4b"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query visualises total emails with Phish detections summarizing the data by email sender IP address (SenderIPv4).
