This section consolidates key visuals that track and explain phish detections in inbound email as identified by Microsoft Defender for Office 365 focusing on top attacked users and top senders.<br><br>**Recommended action:** Enroll the most-targeted users in security awareness training and consider blocking persistent phishing sender domains."},"name":"text - Phish Section3 Banner","id":"f46ed4a8-e2b5-4ccd-ae38-efc571bfc791"},{"type":1,"content":{"json":"### Phish Detections top attacked users
**Displays the top 10 recipient email addresses that received inbound emails flagged as Phish. These users may be at higher risk and should be prioritised for targeted cybersecurity awareness training. Training should cover the specific threat types and techniques they are exposed to, and reinforce best practices for promptly reporting any suspicious messages that might bypass security controls and reach their inbox.**"},"customWidth":"100","name":"text - Phish TopUsers Header","id":"96d9b543-070a-42d4-bbed-3f5cf79ca7ce"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query visualises total inbound emails with Phish detections summarizing the data by the top 15 recipient email address (RecipientEmailAddress).
//The comment in the query excludes deliveries to the SecOps Mailbox and by the Phish Simulation system. Remove the "//" to apply the exclusion.
EmailEvents
| where OrgLevelPolicy != "Phishing simulation" and OrgLevelPolicy != "SecOps Mailbox"
| extend Key = strcat(NetworkMessageId , '-', RecipientEmailAddress) 
| summarize arg_max(Timestamp, *) by Key
| summarize TotalEmailCount=count(),PhishEmailCount = countif(ThreatTypes has "Phish") by RecipientEmailAddress
| extend Bad_Traffic_Percentage_Inbound = todouble(round(PhishEmailCount / todouble(TotalEmailCount) * 100, 2))
| where PhishEmailCount !=0
| top 15 by PhishEmailCount
| project ['Recipient'] = RecipientEmailAddress, ['Phish Emails'] = PhishEmailCount, ['Total Inbound'] = TotalEmailCount, ['Bad Traffic %'] = Bad_Traffic_Percentage_Inbound","size":3,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"table","gridSettings":{"formatters":[{"columnMatch":"Phish Emails","formatter":3,"formatOptions":{"palette":"redDark","customColumnWidthSetting":"30ch"},"numberFormat":{"unit":17,"options":{"style":"decimal"}}},{"columnMatch":"Total Inbound","formatter":0,"formatOptions":{"customColumnWidthSetting":"30ch"},"numberFormat":{"unit":17,"options":{"style":"decimal"}}},{"columnMatch":"Bad Traffic %","formatter":4,"formatOptions":{"palette":"red","min":0,"max":20,"customColumnWidthSetting":"40ch"},"numberFormat":{"unit":1,"options":{"style":"decimal"}}},{"columnMatch":"Emails","formatter":3,"formatOptions":{"palette":"redDark","customColumnWidthSetting":"50ch"},"numberFormat":{"unit":17,"options":{"style":"decimal"}}},{"columnMatch":"count_","formatter":3,"formatOptions":{"palette":"redDark"},"numberFormat":{"unit":17,"options":{"style":"decimal"}}}],"filter":true}},"customWidth":"100","conditionalVisibility":{"parameterName":"Tab","comparison":"isEqualTo","value":"3"},"name":"query - Phish TopRecipients Table","styleSettings":{"margin":"10px","padding":"10px"},"id":"25100115-78d3-4144-b44e-613b44f02484"},{"type":1,"content":{"json":"### Top 10 Sender Domains with Phish Detections (Inbound)
**Displays the top 10 sender domains sending inbound emails detected as Phish. Helps identify external sources most frequently associated with malicious content for prioritised threat monitoring and mitigation.**"},"customWidth":"100","name":"text - Phish TopSenders Header","id":"e7fcb7fe-4bca-4153-a9b0-8ded135b1c64"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query visualises total emails with Phish detections summarizing the data by the top 15 email sender P2 domain (SenderFromDomain), now including the Phish confidence split (High/Normal) and the aggregated phish detection methods seen per domain. Adding additional insights for total inbound emails and bad traffic percentage for each sender domain.
//The comment in the query excludes deliveries to the SecOps Mailbox and by the Phish Simulation system. Remove the "//" to apply the exclusion.
EmailEvents
| where OrgLevelPolicy != "Phishing simulation" and OrgLevelPolicy != "SecOps Mailbox"
| where EmailDirection == "Inbound"
| extend PhishConf = tostring(parse_json(ConfidenceLevel).Phish)
| extend PhishMethods = parse_json(DetectionMethods).Phish
| summarize TotalEmailCount = count(),
            PhishEmailCount = countif(ThreatTypes has "Phish"),
            Phish_High = countif(ThreatTypes has "Phish" and PhishConf == "High"),
            Phish_Normal = countif(ThreatTypes has "Phish" and PhishConf == "Normal"),
            PhishMethodSet = make_set_if(PhishMethods, ThreatTypes has "Phish") by SenderFromDomain
| extend Bad_Traffic_Percentage_Inbound = todouble(round(PhishEmailCount / todouble(TotalEmailCount) * 100, 2))
| where PhishEmailCount != 0
| top 15 by PhishEmailCount
| mv-apply S = PhishMethodSet on ( mv-expand m = S to typeof(string) | summarize Methods = make_set(m) )
| project ['Sender Domain'] = SenderFromDomain, ['Phish Emails'] = PhishEmailCount, ['Phish (High)'] = Phish_High, ['Phish (Normal)'] = Phish_Normal, ['Total Inbound'] = TotalEmailCount, ['Bad Traffic %'] = Bad_Traffic_Percentage_Inbound, ['Detection Methods'] = strcat_array(Methods, ", ")","size":3,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"table","gridSettings":{"formatters":[{"columnMatch":"Phish Emails","formatter":3,"formatOptions":{"palette":"redDark","customColumnWidthSetting":"40ch"},"numberFormat":{"unit":17,"options":{"style":"decimal"}}},{"columnMatch":"Phish (High)","formatter":0,"numberFormat":{"unit":17,"options":{"style":"decimal"}}},{"columnMatch":"Phish (Normal)","formatter":0,"numberFormat":{"unit":17,"options":{"style":"decimal"}}},{"columnMatch":"Total Inbound","formatter":0,"numberFormat":{"unit":17,"options":{"style":"decimal"}}},{"columnMatch":"Bad Traffic %","formatter":4,"formatOptions":{"palette":"red","min":0,"max":20,"customColumnWidthSetting":"50ch"},"numberFormat":{"unit":1,"options":{"style":"decimal"}}},{"columnMatch":"BadEmailCount","formatter":3,"formatOptions":{"palette":"redDark","customColumnWidthSetting":"40ch"},"numberFormat":{"unit":17,"options":{"style":"decimal"}}},{"columnMatch":"Emails","formatter":3,"formatOptions":{"palette":"redDark","customColumnWidthSetting":"50ch"},"numberFormat":{"unit":17,"options":{"style":"decimal"}}},{"columnMatch":"count_","formatter":3,"formatOptions":{"palette":"redDark"},"numberFormat":{"unit":17,"options":{"style":"decimal"}}}],"filter":true}},"customWidth":"100","conditionalVisibility":{"parameterName":"Tab","comparison":"isEqualTo","value":"3"},"name":"query - Phish TopSenders Table","styleSettings":{"margin":"10px","padding":"10px"},"id":"717bfce8-b5d4-4900-99db-4ba0c503591d"}]},"conditionalVisibility":{"parameterName":"Tab","comparison":"isEqualTo","value":"3"},"name":"group - 26-PhishDetectionsTopattackedusers-topsenders","styleSettings":{"margin":"10px","padding":"10px","showBorder":true},"id":"553afca2-caa1-45b1-bec0-dca426b5be46"},{"type":1,"content":{"json":"# Spam Detection Insights

---
This tab provides insights into email message **detections** by Microsoft Defender for Office 365 where the message contained a **Spam threat** within its **email content**, **URLs**, or **attachments**."},"conditionalVisibility":{"parameterName":"Tab","comparison":"isEqualTo","value":"4"},"name":"text - Spam Tab Intro","styleSettings":{"margin":"10px","padding":"10px"},"id":"a693a05a-a772-4ac4-9863-07ad0d1b7092"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//KPI summary of inbound email spam detections for the selected period, with a per-period Trend series feeding each tile sparkline.
let gran = {Granularity};
let sp = EmailEvents | where EmailDirection == "Inbound" | where ThreatTypes has "Spam";
let junk = sp | where DeliveryLocation has "Junk";
let spTrend = toscalar(sp | make-series Trend = count() default = 0 on Timestamp step gran | project Trend);
let junkTrend = toscalar(junk | make-series Trend = count() default = 0 on Timestamp step gran | project Trend);
union
(print Count = toscalar(sp | summarize count()), Details = "Spam Emails", Ord = 1, Trend = spTrend),
(print Count = toscalar(sp | summarize dcount(RecipientEmailAddress)), Details = "Users Targeted", Ord = 2, Trend = spTrend),
(print Count = toscalar(sp | summarize dcount(SenderFromDomain)), Details = "Sender Domains", Ord = 3, Trend = spTrend),
(print Count = toscalar(junk | summarize count()), Details = "Sent to Junk", Ord = 4, Trend = junkTrend)
| sort by Ord asc
| project Count, Details, Trend","size":3,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"tiles","tileSettings":{"titleContent":{"columnMatch":"Details","formatter":1},"leftContent":{"columnMatch":"Count","formatter":12,"formatOptions":{"min":0,"palette":"blue"},"numberFormat":{"unit":17,"options":{"style":"decimal","maximumFractionDigits":1}}},"secondaryContent":{"columnMatch":"Trend","formatter":21,"formatOptions":{"min":0,"palette":"blue"}},"showBorder":true,"size":"auto"}},"customWidth":"100","conditionalVisibility":{"parameterName":"Tab","comparison":"isEqualTo","value":"4"},"name":"spam kpi strip","styleSettings":{"margin":"10px","padding":"10px"},"id":"cadd5331-1db8-4ac8-bc99-42cd5227ee51"},{"type":12,"content":{"version":"NotebookGroup/1.0","groupType":"editable","items":[{"type":1,"content":{"json":"<table style="width:100%; border-collapse:collapse; border:none;background-color:#003366;">
<tr>
<td style="text-align:left; border:none; font-size:20px; font-weight:bold;color:white;width:1%">Spam Detection Effectiveness and Trends
</td>
</tr>
</table>

This section consolidates key visuals that track and explain Spam detections in inbound email as identified by Microsoft Defender for Office 365 focusing on Effectiveness and per-{Granularity} trend. For effectiveness, we consider messages reported by your admins and decisions made post-delivery.<br><br>**Recommended action:** If legitimate mail is marked as spam, review the Spam and Bulk thresholds; if spam is leaking through, tighten them."},"name":"text - Spam Section1 Banner","id":"1093f3b6-cea7-4f54-9029-f9aadd79ca9f"},{"type":12,"content":{"version":"NotebookGroup/1.0","groupType":"editable","items":[{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query calculates the effectiveness of spam detections without edge data.
let minTime = toscalar(EmailEvents | summarize min(Timestamp));
let maxTime = toscalar(EmailEvents | summarize max(Timestamp));
// baseQuery _FN_Admin_Submissions_SPM
let _FN_Admin_Submissions_SPM = toscalar(
CloudAppEvents
| where Timestamp between (minTime .. maxTime)
| where ActionType == "AdminSubmissionSubmitted"
| extend SubmissionType = tostring((parse_json(RawEventData)).SubmissionType)
| extend NetworkMessageId = tostring((parse_json(RawEventData)).ObjectId)
| where SubmissionType in ("0")
| summarize count()
);
// baseQuery _FN_ZAP_Successful_Spam
let _FN_ZAP_Successful_Spam = toscalar(
EmailPostDeliveryEvents
| where ActionTrigger == "SpecialAction" and ActionType == "Spam ZAP" and ActionResult == "Success" and Timestamp between (minTime .. maxTime)
| summarize count()
    //Take all our Spam ZAP, and count how many messages we missed and successfully cleaned up.
);
// baseQuery _FN_ZAP_Unsuccessful_Spam
let _FN_ZAP_Unsuccessful_Spam = toscalar(
EmailPostDeliveryEvents
| where ActionTrigger == "SpecialAction" and ActionType == "Spam ZAP" and ActionResult != "Success" and Timestamp between (minTime .. maxTime)
| summarize count()
//Take all our Spam ZAP, and count how many messages we failed to clean up due to error or users/admins/API vendors getting to the message first.
);
// baseQuery _SPAM_ZAP_FP
let _SPAM_ZAP_FP = toscalar(
EmailPostDeliveryEvents
| where ActionTrigger == "SpecialAction" and Action has_any ("Redelivery","Reprocessed") and Timestamp between (minTime .. maxTime)
| join kind=leftsemi (
            EmailEvents
            | where Timestamp between (minTime ..maxTime )
            | where ThreatTypes contains "Spam"
            | project NetworkMessageId, ThreatTypes)
            on NetworkMessageId
| summarize count()
// count all the FPs which were originally Spam, and when we TT'd them were not so we can subtract that from our mailfow catch, and therefore the total true bad.
);
// baseQuery _Spam_Mailflow
let _Spam_Mailflow = toscalar(
EmailEvents
| where EmailDirection == "Inbound" and ThreatTypes == "Spam" and Timestamp between (minTime .. maxTime)
| extend Key = strcat(NetworkMessageId , '-', RecipientEmailAddress) 
| summarize arg_max(Timestamp, *) by Key
| summarize count()
// Get all the mailflow detected as SPM, then count all the NMIDs (not distinct)
);
print
