---
This tab focuses on the highest-value email threat class: **impersonation and Business Email Compromise (BEC)**. It brings together impersonation and spoof detections, sender authentication (DMARC, DKIM, SPF, CompAuth), supply-chain and partner-compromise correlation, and first-contact / new-vendor senders - the signals that precede targeted financial and credential attacks. It is the email-side companion to the impersonation insights on the **Teams &amp; Collaboration** tab."},"name":"text - impersonation bec description","conditionalVisibility":{"parameterName":"Tab","comparison":"isEqualTo","value":"15"},"id":"fda8ccd5-fafc-457a-a6a2-05b504be1023"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//KPI summary of inbound email impersonation and spoof (BEC) detections for the selected period, with a per-period Trend series feeding each tile sparkline.
let gran = {Granularity};
let bec = EmailEvents | where EmailDirection == "Inbound" | where DetectionMethods has "Impersonation" or DetectionMethods has "Spoof";
let inbox = bec | where DeliveryLocation has "Inbox";
let becTrend = toscalar(bec | make-series Trend = count() default = 0 on Timestamp step gran | project Trend);
let inboxTrend = toscalar(inbox | make-series Trend = count() default = 0 on Timestamp step gran | project Trend);
union
(print Count = toscalar(bec | summarize count()), Details = "Impersonation / Spoof Emails", Ord = 1, Trend = becTrend),
(print Count = toscalar(bec | summarize dcount(RecipientEmailAddress)), Details = "Users Targeted", Ord = 2, Trend = becTrend),
(print Count = toscalar(bec | summarize dcount(SenderFromDomain)), Details = "Spoofed Sender Domains", Ord = 3, Trend = becTrend),
(print Count = toscalar(inbox | summarize count()), Details = "Delivered to Inbox", Ord = 4, Trend = inboxTrend)
| sort by Ord asc
| project Count, Details, Trend","size":3,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"tiles","tileSettings":{"titleContent":{"columnMatch":"Details","formatter":1},"leftContent":{"columnMatch":"Count","formatter":12,"formatOptions":{"min":0,"palette":"blue"},"numberFormat":{"unit":17,"options":{"style":"decimal","maximumFractionDigits":1}}},"secondaryContent":{"columnMatch":"Trend","formatter":21,"formatOptions":{"min":0,"palette":"blue"}},"showBorder":true,"size":"auto"}},"customWidth":"100","conditionalVisibility":{"parameterName":"Tab","comparison":"isEqualTo","value":"15"},"name":"bec kpi strip","styleSettings":{"margin":"10px","padding":"10px"},"id":"91fdd28f-31c4-4f94-b60a-12cd97d44ddf"},{"type":12,"content":{"version":"NotebookGroup/1.0","groupType":"editable","items":[{"type":1,"content":{"json":"<table style="width:100%; border-collapse:collapse; border:none;background-color:#003366;">
