**Correlates the external domains your organization emails most with inbound emails from those same domains that carried threats. A trusted partner or supplier domain suddenly sending threats is a strong signal that the partner may be compromised - a common supply-chain and business email compromise (BEC) vector.**<br><br>**Recommended action:** Verify any flagged partner through a trusted channel before acting on their recent messages, alert them to a possible compromise, and consider tightening inbound policy for that domain until confirmed clean."},"customWidth":"100","name":"text - Phish Partner Compromise Header","id":"2c62c576-3b05-4663-ae2e-4f961d7409c6"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query visualises top outbound recipient domains by outbound email volume and shows total number of inbound emails with Threats from the same domains (as inbound senders) 
EmailEvents
| where OrgLevelPolicy != "Phishing simulation" and OrgLevelPolicy != "SecOps Mailbox"
| extend Key = strcat(NetworkMessageId , '-', RecipientEmailAddress) 
| summarize arg_max(Timestamp, *) by Key
| where EmailDirection == "Outbound"
| project RecipientDomain = tostring(split(RecipientEmailAddress, "@")[1])
| summarize count() by RecipientDomain
| project OutboundCount=count_, RecipientDomain, SenderFromDomain=RecipientDomain
| join (EmailEvents | where EmailDirection == "Inbound" and isempty(ThreatTypes)==false) on SenderFromDomain
| summarize max(OutboundCount),count() by SenderFromDomain
| project SenderFromDomain, OutboundEmails=max_OutboundCount, IncomingEmailsWithThreats=count_
| extend Bad_Traffic_Percentage = todouble(round(IncomingEmailsWithThreats / todouble(OutboundEmails) * 100, 2))
| top 15 by OutboundEmails
| project ['Sender Domain'] = SenderFromDomain, ['Outbound Emails'] = OutboundEmails, ['Inbound w/ Threats'] = IncomingEmailsWithThreats, ['Bad Traffic %'] = Bad_Traffic_Percentage","size":0,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"gridSettings":{"formatters":[{"columnMatch":"Outbound Emails","formatter":0,"numberFormat":{"unit":17,"options":{"style":"decimal"}}},{"columnMatch":"Inbound w/ Threats","formatter":3,"formatOptions":{"palette":"redDark","customColumnWidthSetting":"60ch"},"numberFormat":{"unit":17,"options":{"style":"decimal"}}},{"columnMatch":"Bad Traffic %","formatter":4,"numberFormat":{"unit":1,"options":{"style":"decimal"}},"formatOptions":{"palette":"red","min":0,"max":20}}],"filter":true}},"customWidth":"100","name":"query - Phish Partner Compromise","styleSettings":{"margin":"10px","padding":"10px"},"id":"1aaa047c-1108-4288-833e-61ca35b5495a"},{"type":1,"content":{"json":"### Top Recipients Targeted by Impersonation / BEC
**Lists the recipients most frequently targeted by impersonation and Business Email Compromise (BEC) attempts, showing the number of impersonation emails, how many distinct senders were involved, the top spoofed sender domains, and how many of those messages were delivered to the inbox. Helps identify high-risk users (often executives or finance staff) who may need extra protection or awareness.**"},"customWidth":"100","name":"text - impersonation targets","id":"b1e7c2a4-9f3d-4a6b-8c12-7d5e9f0a1b23"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//Top recipients targeted by impersonation / BEC, with distinct senders, spoofed domains and how many landed in the inbox.
EmailEvents
| where EmailDirection == "Inbound"
| where OrgLevelPolicy !in ("Phishing simulation", "SecOps Mailbox")
| where DetectionMethods has "Impersonation"
| extend Key = strcat(NetworkMessageId, "-", RecipientEmailAddress)
| summarize arg_max(Timestamp, *) by Key
| summarize ImpersonationEmails = count(),
            DistinctSenders      = dcount(SenderFromAddress),
            TopSpoofedDomains    = make_set(SenderFromDomain, 5),
            DeliveredToInbox     = countif(DeliveryLocation has "Inbox")
        by RecipientEmailAddress
| top 20 by ImpersonationEmails
