---
This tab provides insights into **URL-based detections** in email messages and details about URL clicks performed by end users on URLs identified as **malicious**."},"conditionalVisibility":{"parameterName":"Tab","comparison":"isEqualTo","value":"5"},"name":"text - 24 - Copy - Copy","styleSettings":{"margin":"10px","padding":"10px"},"id":"2156430d-fec6-48bb-a9a8-3166182f6993"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//KPI summary of URL threat protection (Safe Links clicks and URLs seen in email) for the selected period, with a per-period Trend series feeding each tile sparkline.
let gran = {Granularity};
let clicks = UrlClickEvents;
let blocked = clicks | where ActionType in ("ClickBlocked","ClickBlockedByTenantPolicy");
let allowed = clicks | where ActionType == "ClickAllowed";
let blockedTrend = toscalar(blocked | make-series Trend = count() default = 0 on Timestamp step gran | project Trend);
let allowedTrend = toscalar(allowed | make-series Trend = count() default = 0 on Timestamp step gran | project Trend);
let usersTrend = toscalar(clicks | make-series Trend = dcount(AccountUpn) default = 0 on Timestamp step gran | project Trend);
let urlsTrend = toscalar(EmailUrlInfo | make-series Trend = dcount(Url) default = 0 on Timestamp step gran | project Trend);
union
(print Count = toscalar(blocked | summarize count()), Details = "Malicious Clicks Blocked", Ord = 1, Trend = blockedTrend),
(print Count = toscalar(allowed | summarize count()), Details = "Clicks Allowed Through", Ord = 2, Trend = allowedTrend),
(print Count = toscalar(clicks | summarize dcount(AccountUpn)), Details = "Users Clicking Links", Ord = 3, Trend = usersTrend),
(print Count = toscalar(EmailUrlInfo | summarize dcount(Url)), Details = "Distinct URLs in Email", Ord = 4, Trend = urlsTrend)
| sort by Ord asc
| project Count, Details, Trend","size":3,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"tiles","tileSettings":{"titleContent":{"columnMatch":"Details","formatter":1},"leftContent":{"columnMatch":"Count","formatter":12,"formatOptions":{"min":0,"palette":"blue"},"numberFormat":{"unit":17,"options":{"style":"decimal","maximumFractionDigits":1}}},"secondaryContent":{"columnMatch":"Trend","formatter":21,"formatOptions":{"min":0,"palette":"blue"}},"showBorder":true,"size":"auto"}},"customWidth":"100","conditionalVisibility":{"parameterName":"Tab","comparison":"isEqualTo","value":"5"},"name":"url kpi strip","styleSettings":{"margin":"10px","padding":"10px"},"id":"d5e2326a-a5dd-4217-bb75-0e337d75d306"},{"type":12,"content":{"version":"NotebookGroup/1.0","groupType":"editable","items":[{"type":1,"content":{"json":"<table style="width:100%; border-collapse:collapse; border:none;background-color:#003366;">
<tr>
