This section consolidates key visuals that track and explain URL based threat detections in inbound email as identified by Microsoft Defender for Office 365 focusing on per-{Granularity} trends of URL-based threat detections, QR code detections, and URL scans activity by locations.<br><br>**Recommended action:** Confirm Safe Links is enabled for email and Teams; investigate QR-code and URL detection spikes for emerging campaigns."},"name":"text - 13 - Copy","id":"ed3468e7-1936-45fd-9168-93010a662302"},{"type":1,"content":{"json":"### Trend of URL-Based Malware Threat Detections<br>

**This visual displays a per-{Granularity} trend of emails with URL based Malware threat detections identified by Microsoft Defender for Office 365. The line chart summarises the number of messages flagged for malware threats.**"},"name":"text - 13 - Copy - Copy","id":"77e7bbac-d752-478b-bce9-06bb1bd12bfe"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query visualises total emails with Malware detections over time summarizing the data daily by various Malware URL threat based detection technologies/controls in Microsoft Defender for Office 365.
let gran = {Granularity};
let agg = materialize(EmailEvents
| where DetectionMethods has 'Malware'
| where OrgLevelPolicy != "Phishing simulation" and OrgLevelPolicy != "SecOps Mailbox"
| extend Key = strcat(NetworkMessageId , '-', RecipientEmailAddress) 
| summarize arg_max(Timestamp, *) by Key
| extend ParsedMethods = parse_json(DetectionMethods)
| mv-expand MalwareMethod = ParsedMethods.Malware
| where MalwareMethod contains "URL"
| summarize Count = count() by MalwareMethod = tostring(MalwareMethod), Timestamp = bin(Timestamp, gran));
range Timestamp from toscalar(agg | summarize min(Timestamp)) to toscalar(agg | summarize max(Timestamp)) step gran
| extend d = 1 | join kind=inner (agg | distinct MalwareMethod | extend d = 1) on d | project Timestamp, MalwareMethod
| join kind=leftouter (agg) on Timestamp, MalwareMethod
| project Timestamp, MalwareMethod, Count = coalesce(Count, 0)
| sort by MalwareMethod asc, Timestamp asc","size":0,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"linechart"},"customWidth":"100","name":"query - 8 - Copy","styleSettings":{"margin":"10px","padding":"10px"},"id":"79ef5e7b-57a6-4519-9899-18fd8cae5e68"},{"type":1,"content":{"json":"### Trend of URL-Based Phish Threat Detections<br>

**This visual displays a per-{Granularity} trend of emails with URL based Phish threat detections identified by Microsoft Defender for Office 365. The line chart summarises the number of messages flagged for Phish threats.**"},"name":"text - 13 - Copy - Copy - Copy","id":"48923812-5440-4f47-8881-273f14cbfb8e"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query visualises total emails with Phishing detections over time summarizing the data daily by various Phishing URL threat based detection technologies/controls in Microsoft Defender for Office 365.
let gran = {Granularity};
let agg = materialize(EmailEvents
| where DetectionMethods has 'Phish'
| where OrgLevelPolicy != "Phishing simulation" and OrgLevelPolicy != "SecOps Mailbox"
| extend Key = strcat(NetworkMessageId , '-', RecipientEmailAddress) 
| summarize arg_max(Timestamp, *) by Key
| extend ParsedMethods = parse_json(DetectionMethods)
| mv-expand PhishMethod = ParsedMethods.Phish
| where PhishMethod contains "URL"
| summarize Count = count() by PhishMethod = tostring(PhishMethod), Timestamp = bin(Timestamp, gran));
range Timestamp from toscalar(agg | summarize min(Timestamp)) to toscalar(agg | summarize max(Timestamp)) step gran
| extend d = 1 | join kind=inner (agg | distinct PhishMethod | extend d = 1) on d | project Timestamp, PhishMethod
