options":{"style":"decimal"}}}],"filter":true}},"customWidth":"100","name":"query - 18 - Copy - Copy - Copy","styleSettings":{"margin":"10px","padding":"10px"},"id":"734ee45e-4dff-4ca1-b17d-02389086b17b"}]},"conditionalVisibility":{"parameterName":"Tab","comparison":"isEqualTo","value":"5"},"name":"group - 32-Top clickers","styleSettings":{"margin":"10px","padding":"10px","showBorder":true},"id":"ee6c3413-28be-49a1-a89d-bf5fce7acfa4"},{"type":1,"content":{"json":"# Microsoft Teams Collaboration Protection

---
As email defenses mature, attackers are shifting into **Microsoft Teams**, where messages bypass secure email gateways and carry the implicit trust of a colleague chat. Microsoft Threat Intelligence reports Teams-based phishing and voice phishing (vishing) rising steadily through 2026, most often as **IT help desk or technical-support impersonation** from external or newly-created tenants, used to steer users toward remote-access tools and credential theft.

This tab shows **Microsoft Defender for Office 365** protection for Microsoft Teams: threat detections and impersonation, suspicious external senders, malicious URLs and clicks, malicious files, post-delivery ZAP removals, and user and admin submissions across chats and channels.

**Recommended action:** Treat unsolicited external help desk or IT support contact as suspicious. Restrict inbound chat from unmanaged and consumer tenants, allowlist trusted external domains, remove or restrict remote-support tools such as Quick Assist where they are not required, and enforce phishing-resistant MFA for all users (Conditional Access with authentication strength), prioritizing privileged and administrator accounts first.

[<p><b>Disrupting threats targeting Microsoft Teams</b></p>](https://www.microsoft.com/en-us/security/blog/2025/10/07/disrupting-threats-targeting-microsoft-teams/)[<p><b>Cross-tenant helpdesk impersonation to data exfiltration: a human-operated intrusion playbook</b></p>](https://www.microsoft.com/en-us/security/blog/2026/04/18/crosstenant-helpdesk-impersonation-data-exfiltration-human-operated-intrusion-playbook/)[<p><b>Help on the line: how a Microsoft Teams support call led to compromise</b></p>](https://www.microsoft.com/en-us/security/blog/2026/03/16/help-on-the-line-how-a-microsoft-teams-support-call-led-to-compromise/)[<p><b>Email threat landscape: Q2 2026 trends and insights</b></p>](https://www.microsoft.com/en-us/security/blog/2026/07/23/email-threat-landscape-q2-2026-trends-and-insights/)"},"conditionalVisibility":{"parameterName":"Tab","comparison":"isEqualTo","value":"14"},"name":"text - teams description","styleSettings":{"margin":"10px","padding":"10px"},"id":"5c0f0100-0a11-4b22-9c33-000000000100"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//Headline Microsoft Teams protection metrics for the selected period, with per-interval sparklines. Messages are de-duplicated to the latest record per Teams message.
let gran = {Granularity};
let msgs = materialize(MessageEvents | summarize arg_max(Timestamp, *) by TeamsMessageId);
let zap = materialize(MessagePostDeliveryEvents);
union
(msgs | summarize Count = count() | extend Details = "Teams Messages Scanned", Ord = 1, Trend = toscalar(msgs | make-series S = count() default = 0 on Timestamp step gran | project S)),
(msgs | where isnotempty(ThreatTypes) | summarize Count = count() | extend Details = "Messages with Threats", Ord = 2, Trend = toscalar(msgs | where isnotempty(ThreatTypes) | make-series S = count() default = 0 on Timestamp step gran | project S)),
(msgs | where ThreatTypes has "Phish" | summarize Count = count() | extend Details = "Phish Detections", Ord = 3, Trend = toscalar(msgs | where ThreatTypes has "Phish" | make-series S = count() default = 0 on Timestamp step gran | project S)),
(msgs | where ThreatTypes has "Malware" | summarize Count = count() | extend Details = "Malware Detections", Ord = 4, Trend = toscalar(msgs | where ThreatTypes has "Malware" | make-series S = count() default = 0 on Timestamp step gran | project S)),
(msgs | where ThreatTypes has "Spam" | summarize Count = count() | extend Details = "Spam Detections", Ord = 5, Trend = toscalar(msgs | where ThreatTypes has "Spam" | make-series S = count() default = 0 on Timestamp step gran | project S)),
(msgs | where SafetyTip == "URLMessageWarning" | summarize Count = count() | extend Details = "Messages with URL Warning", Ord = 6, Trend = toscalar(msgs | where SafetyTip == "URLMessageWarning" | make-series S = count() default = 0 on Timestamp step gran | project S)),
(zap | summarize Count = count() | extend Details = "Post-Delivery ZAP Actions", Ord = 7, Trend = toscalar(zap | make-series S = count() default = 0 on Timestamp step gran | project S))
| sort by Ord asc
| project Details, Count, Trend","size":3,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"tiles","tileSettings":{"titleContent":{"columnMatch":"Details","formatter":1},"leftContent":{"columnMatch":"Count","formatter":12,"formatOptions":{"min":0,"palette":"blue"},"numberFormat":{"unit":17,"options":{"style":"decimal","maximumFractionDigits":1}}},"secondaryContent":{"columnMatch":"Trend","formatter":21},"showBorder":true,"size":"auto"}},"customWidth":"100","name":"teams kpi tiles","styleSettings":{"margin":"10px","padding":"10px"},"id":"b2c476ca-4141-43b4-9d4e-98470aa432fc","conditionalVisibility":{"parameterName":"Tab","comparison":"isEqualTo","value":"14"}},{"type":12,"content":{"version":"NotebookGroup/1.0","groupType":"editable","items":[{"type":1,"content":{"json":"<table style="width:100%; border-collapse:collapse; border:none;background-color:#003366;">
<tr>
<td style="text-align:left; border:none; font-size:20px; font-weight:bold;color:white;width:1%">Microsoft Teams - Collaboration Protection Overview
</td>
</tr>
</table>

Microsoft Defender for Office 365 extends its protection to **Microsoft Teams**, detecting malicious messages, URLs, and files shared through chats and channels. This tab summarizes Teams message detections, link-safety warnings, post-delivery ZAP, file scanning, and user/admin submissions.<br><br>*Scope note: the Teams message tables surface metadata for external-conversation messages plus internal messages that contain URLs, so counts reflect that scope rather than the full volume of Teams messages.*"},"name":"teams overview banner","id":"2f71360f-1673-480f-8361-5afc83aee67d"},{"type":1,"content":{"json":"### Teams threat detections over time<br>

**Volume (per selected interval) of Microsoft Teams messages detected with a threat by Microsoft Defender for Office 365. Spikes may indicate a targeted Teams-based campaign.**"},"customWidth":"100","name":"teams trend header","styleSettings":{"margin":"10px","padding":"0px"},"id":"0ac71d4e-8ecb-4d17-9fd3-10754007ec07"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query visualises the number of Microsoft Teams messages detected with a threat over time, de-duplicated to the latest record per message and summarized per selected interval.
let gran = {Granularity};
let minTime = toscalar(MessageEvents | summarize min(Timestamp));
let maxTime = toscalar(MessageEvents | summarize max(Timestamp));
let agg = materialize(MessageEvents | where isnotempty(ThreatTypes) | summarize arg_max(Timestamp, *) by TeamsMessageId | summarize ThreatDetections = count() by Timestamp = bin(Timestamp, gran));
range Timestamp from bin(minTime, gran) to bin(maxTime, gran) step gran
| join kind=leftouter (agg) on Timestamp
| project Timestamp, ThreatDetections = coalesce(ThreatDetections, 0)
| sort by Timestamp asc","size":0,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"areachart","chartSettings":{"xAxis":"Timestamp","seriesLabelSettings":[{"seriesName":"ThreatDetections","color":"blueDark"}]}},"customWidth":"100","name":"teams detection trend","styleSettings":{"margin":"10px","padding":"10px"},"id":"937f3bc6-21f5-4f4c-ab72-78f08f32c5bd"},{"type":1,"content":{"json":"### Threat type breakdown<br>

**Split of Microsoft Teams threat detections across Phish, Malware, and Spam.**"},"customWidth":"50","name":"teams threat pie header","styleSettings":{"margin":"10px","padding":"0px"},"id":"645a39ae-843a-47db-8016-6082ef37744d"},{"type":1,"content":{"json":"### Thread exposure<br>

**De-duplicated Microsoft Teams messages split by whether the conversation includes external participants.**"},"customWidth":"50","name":"teams thread header","id":"a1a48f9a-8593-4ab5-8824-5998c643e844"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query breaks down Microsoft Teams threat detections by threat type for the selected period, de-duplicated to the latest record per message. A message flagged for more than one threat type is counted under each, so the split can exceed the distinct message count.
let msgs = MessageEvents | where isnotempty(ThreatTypes) | summarize arg_max(Timestamp, *) by TeamsMessageId;
union
(msgs | where ThreatTypes has "Phish" | summarize Count = count() | extend ThreatType = "Phish"),
(msgs | where ThreatTypes has "Malware" | summarize Count = count() | extend ThreatType = "Malware"),
(msgs | where ThreatTypes has "Spam" | summarize Count = count() | extend ThreatType = "Spam")
| project ThreatType, Count","size":3,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"piechart"},"customWidth":"50","name":"teams threat type pie","styleSettings":{"margin":"10px","padding":"10px"},"id":"029b4ecc-cd95-4385-a251-8ab194add8f4"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query shows de-duplicated Microsoft Teams messages split by whether the thread includes external participants.
MessageEvents
| summarize arg_max(Timestamp, *) by TeamsMessageId
| extend Thread = iif(IsExternalThread == true, "External Thread", "Internal Thread")
| summarize Count = count() by Thread","size":3,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"piechart"},"customWidth":"50","name":"teams thread pie","styleSettings":{"margin":"10px","padding":"10px"},"id":"1581f447-9b3e-4857-84b8-e78b5df65ac5"}]},"conditionalVisibility":{"parameterName":"Tab","comparison":"isEqualTo","value":"14"},"name":"group - Teams Overview","styleSettings":{"margin":"10px","padding":"10px","showBorder":true},"id":"283f36b2-5c54-4afe-9a87-33d4796bd5b7"},{"type":12,"content":{"version":"NotebookGroup/1.0","groupType":"editable","items":[{"type":1,"content":{"json":"<table style="width:100%; border-collapse:collapse; border:none;background-color:#003366;">
<tr>
<td style="text-align:left; border:none; font-size:20px; font-weight:bold;color:white;width:1%">Teams Calls and Vishing (Voice Phishing)
</td>
</tr>
</table>

**Voice phishing (vishing) over Microsoft Teams is the fastest-growing collaboration threat of 2026. Attackers impersonate IT help desk or support and call users directly, often after a chat lure, to talk them into granting remote access or entering credentials. Because a target must be online to answer, malicious calls cluster in working hours. This section surfaces Teams call activity, when calls happen, and callers using support or brand-impersonation identities.**<br><br>*Interim data source: Teams call activity is currently read from Microsoft Defender for Cloud Apps call telemetry (CloudAppEvents). It will move to the dedicated CallActivityEvents table once that table is available to stream into Microsoft Sentinel.*<br><br>**Recommended action:** Treat unsolicited help desk or support calls as suspicious. Confirm any request through a known internal channel, and never grant remote access such as Quick Assist on the strength of an inbound Teams call. Restrict inbound calls and chat from unmanaged and consumer tenants."},"customWidth":"100","name":"teams calls banner","id":"9815bdc9-9e10-4e84-9164-783092b4ccb0"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//Teams call and vishing headline metrics for the selected period, with per-interval sparklines. Interim source: Defender for Cloud Apps call telemetry (CloudAppEvents / CallParticipantDetail).
let gran = {Granularity};
let calls = materialize(CloudAppEvents | where ActionType == "CallParticipantDetail" | extend R = parse_json(RawEventData) | extend CallId = tostring(R.CallId), UId = tolower(tostring(R.UserId)));
let susp = calls | extend Local = tostring(split(UId, "@")[0]), Dom = tostring(split(UId, "@")[1]) | where Local matches regex @"(?i)help ?desk|helpdesk|it ?support|service ?desk|sys ?admin|administrator|security|microsoft|google|apple|amazon|paypal|support|update|verif|account|password|mfa|maintenance" or Dom endswith ".onmicrosoft.com";
let reported = CloudAppEvents | where ActionType == "CallReported";
union
(calls | summarize Count = dcount(CallId) | extend Details = "Teams Calls", Ord = 1, Trend = toscalar(calls | make-series S = count() default = 0 on Timestamp step gran | project S)),
(susp | summarize Count = dcount(UId) | extend Details = "Impersonation-style Callers", Ord = 2, Trend = toscalar(susp | make-series S = count() default = 0 on Timestamp step gran | project S)),
(reported | summarize Count = count() | extend Details = "Reported Suspicious Calls", Ord = 3, Trend = toscalar(reported | make-series S = count() default = 0 on Timestamp step gran | project S))
| sort by Ord asc
| project Details, Count, Trend","size":3,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"tiles","tileSettings":{"titleContent":{"columnMatch":"Details","formatter":1},"leftContent":{"columnMatch":"Count","formatter":12,"formatOptions":{"min":0,"palette":"blue"},"numberFormat":{"unit":17,"options":{"style":"decimal","maximumFractionDigits":1}}},"secondaryContent":{"columnMatch":"Trend","formatter":21},"showBorder":true,"size":"auto"},"showAnalytics":true},"customWidth":"100","name":"teams calls kpi","id":"be8946d9-1eae-405c-b8df-cee2242cb44d"},{"type":1,"content":{"json":"### Teams call activity over time<br>
**Distinct Microsoft Teams calls per selected interval. A sudden rise, or calls outside normal working hours, can indicate a vishing campaign in progress.**"},"customWidth":"100","name":"teams calls trend header","id":"1b49c98f-e5d9-457c-b058-a195e89eac0e"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//Distinct Teams calls per interval (interim source: CloudAppEvents / CallParticipantDetail).
CloudAppEvents
| where ActionType == "CallParticipantDetail"
| extend R = parse_json(RawEventData)
| extend CallId = tostring(R.CallId)
| summarize ['Teams Calls'] = dcount(CallId) by Timestamp = bin(Timestamp, {Granularity})
| sort by Timestamp asc","size":0,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"areachart","chartSettings":{"xAxis":"Timestamp","seriesLabelSettings":[{"seriesName":"Teams Calls","color":"blueDark"}]},"showAnalytics":true},"customWidth":"100","name":"teams calls trend","id":"7538b3ca-b96d-421a-9cdc-69b8aef4b185"},{"type":1,"content":{"json":"### When calls happen (hour of day, UTC)<br>
**Microsoft Teams calls by the hour of day they started (UTC), listed 00:00 through 23:00. The bar length is the number of calls that started in that hour across the selected period. Vishing calls cluster in working hours because the target must be online to answer, with the heaviest malicious-call activity between 14:00 and 20:00 UTC, Monday to Friday, according to Microsoft Threat Intelligence. Use this to baseline normal call timing and spot unusual off-hours spikes.**"},"customWidth":"100","name":"teams calls hour header","id":"6bc095e9-fe0d-4f6f-81bd-f3374d758229"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//Teams calls by start hour of day (UTC), all 24 hours 00:00..23:00 in order (interim source: CloudAppEvents / CallParticipantDetail).
let data = CloudAppEvents
| where ActionType == "CallParticipantDetail"
| extend R = parse_json(RawEventData)
| extend JoinTime = todatetime(R.JoinTime), CallId = tostring(R.CallId)
| where isnotempty(JoinTime) and isnotempty(CallId)
| summarize CallStart = min(JoinTime) by CallId
| extend HourUTC = hourofday(CallStart)
| summarize Calls = count() by HourUTC;
range HourUTC from 0 to 23 step 1
| join kind=leftouter (data) on HourUTC
| extend Calls = coalesce(Calls, 0)
| extend HourLabel = strcat(iif(HourUTC < 10, strcat("0", tostring(HourUTC)), tostring(HourUTC)), ":00")
| order by HourUTC asc
| project ['Hour of Day (UTC)'] = HourLabel, ['Teams Calls'] = Calls","size":0,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"table","gridSettings":{"filter":true,"formatters":[{"columnMatch":"Teams Calls","formatter":3,"formatOptions":{"palette":"blueDark","customColumnWidthSetting":"360px"},"numberFormat":{"unit":17,"options":{"style":"decimal","maximumFractionDigits":1}}}]},"showAnalytics":true},"customWidth":"100","name":"teams calls hour","id":"c36a9909-5570-4fe7-8efc-1b9b4745713a"},{"type":1,"content":{"json":"### Suspicious callers (support and helpdesk impersonation)<br>
**Teams call participants whose display name or address looks like IT support, help desk, or a well-known brand (for example "Microsoft IT support", "Help Desk", "Office 365 Support"), or who dial in from a throwaway `.onmicrosoft.com` tenant. Origin shows whether the caller is external, an external throwaway tenant, or inside your own tenant. External and throwaway-tenant callers are the primary vishing risk; own-tenant matches are frequently a legitimate internal help desk and should be confirmed rather than assumed malicious.**<br><br>**Recommended action:** Prioritise External and `.onmicrosoft` callers, confirm none are legitimate, and warn the users they called. Genuine IT support does not cold-call staff over Teams to request remote access."},"customWidth":"100","name":"teams calls susp header","id":"aa420b5f-efd2-4da5-ab41-192031f62ed1"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//Suspicious Teams callers by impersonation-style DISPLAY NAME or address (Attendees[].DisplayName / UPN), with Origin from the org's own accepted (EmailEvents inbound) domains - no tenant-id anchor. Interim source: CloudAppEvents / CallParticipantDetail.
let suspRegex = @"(?i)help ?desk|helpdesk|it ?support|service ?desk|sys ?admin|administrator|security|microsoft|google|apple|amazon|paypal|support|update|verif|account|password|mfa|maintenance";
let ownDomains = toscalar(EmailEvents | where EmailDirection == "Inbound" | extend RD = tolower(tostring(split(RecipientEmailAddress, "@")[1])) | where isnotempty(RD) | summarize make_set(RD, 200));
let calls = CloudAppEvents
| where ActionType == "CallParticipantDetail"
| extend R = parse_json(RawEventData)
| extend CallId = tostring(R.CallId), JoinTime = todatetime(R.JoinTime), Attendees = R.Attendees
| where isnotempty(CallId);
let callAtt = calls | summarize Attendees = take_any(Attendees), JoinTime = min(JoinTime) by CallId;
callAtt
| mv-expand Att = Attendees
| extend Caller = tolower(tostring(Att.UPN)), CallerName = tostring(Att.DisplayName)
| extend CallerDom = tostring(split(Caller, "@")[1])
| where isnotempty(Caller)
| extend SuspName = CallerName matches regex suspRegex or Caller matches regex suspRegex
| where SuspName or CallerDom endswith ".onmicrosoft.com"
| extend Origin = case(CallerDom endswith ".onmicrosoft.com", "External (.onmicrosoft throwaway)", set_has_element(ownDomains, CallerDom), "Own tenant", "External")
| summarize CallsPlaced = dcount(CallId), FirstSeen = min(JoinTime), LastSeen = max(JoinTime) by CallerName, Caller, Origin
| extend OriginRank = case(Origin == "External (.onmicrosoft throwaway)", 0, Origin == "External", 1, 2)
| sort by OriginRank asc, CallsPlaced desc
| take 10
| project ['Caller Display Name'] = CallerName, ['Caller Address'] = Caller, ['Origin'] = Origin, ['Calls Placed'] = CallsPlaced, ['First Seen'] = FirstSeen, ['Last Seen'] = LastSeen","size":0,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"table","gridSettings":{"filter":true,"formatters":[{"columnMatch":"Calls Placed","formatter":3,"formatOptions":{"palette":"redDark","customColumnWidthSetting":"130px"},"numberFormat":{"unit":17,"options":{"style":"decimal","maximumFractionDigits":1}}}]},"showAnalytics":true},"customWidth":"100","name":"teams calls susp table","id":"d1c4df7b-db07-4c4c-bc71-dfd8623cd704"}]},"conditionalVisibility":{"parameterName":"Tab","comparison":"isEqualTo","value":"14"},"name":"group - Teams Calls and Vishing","styleSettings":{"margin":"10px","padding":"10px","showBorder":true},"id":"1d133411-9b5c-4ede-8502-68b3b02262e4"},{"type":12,"content":{"version":"NotebookGroup/1.0","groupType":"editable","items":[{"type":1,"content":{"json":"<table style="width:100%; border-collapse:collapse; border:none;background-color:#003366;">
<tr>
<td style="text-align:left; border:none; font-size:20px; font-weight:bold;color:white;width:1%">Teams Impersonation &amp; Identity Deception
</td>
</tr>
</table>

Microsoft Defender for Office 365 flags Teams messages where a sender impersonates a brand, a specific person, or a trusted domain. Impersonation is the entry point for most Teams social-engineering: attackers pose as IT, executives, or Microsoft to build trust before delivering a malicious link or request. These visuals expose <b>who is being impersonated, who is being targeted, and the infrastructure (display names, look-alike domains, and URLs)</b> behind the campaigns so you can hunt IOCs and coach at-risk users.<br><br>**Recommended action:** Treat the impersonated display names and look-alike domains below as IOCs to hunt, and prioritize the Microsoft Defender alert *Microsoft Teams chat initiated by a suspicious external user*. Teach users that a Teams display name is not proof of identity: verify the real sender domain, and confirm any help desk, executive, or Microsoft support request through a known internal channel before acting."},"name":"teams imp banner","id":"7ff04ff3-9f2d-4a49-8383-2b542d78fe9b"},{"type":3,"content":{"version":"KqlItem/1.0","query":"let imp = CloudAppEvents
| where ActionType == "TeamsImpersonationDetected"
| extend RD = parse_json(RawEventData)
| extend ImpersonationType = tostring(RD.ImpersonationType),
         FakeDisplayName   = tostring(RD.Sender.DisplayName),
         FakeSenderAddress = tostring(RD.Sender.UPN),
         ChatThreadId      = tostring(RD.ChatThreadId),
         TargetUser        = tostring(RD.UserId)
| extend FakeSenderDomain = tostring(split(FakeSenderAddress, "@")[1]);
union
(imp | summarize Count=count() | extend Details="Impersonation Detections", Ord=1),
(imp | summarize Count=dcount(FakeSenderAddress) | extend Details="Distinct Fake Senders", Ord=2),
(imp | summarize Count=dcount(TargetUser) | extend Details="Targeted Users", Ord=3),
(imp | summarize Count=dcount(ImpersonationType) | extend Details="Impersonation Types", Ord=4)
| sort by Ord asc | project Count, Details","size":3,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"tiles","tileSettings":{"titleContent":{"columnMatch":"Details","formatter":1},"secondaryContent":{"columnMatch":"Count","formatter":12,"formatOptions":{"min":0,"palette":"blue"},"numberFormat":{"unit":17,"options":{"style":"decimal","maximumFractionDigits":1}}},"showBorder":true,"size":"full"}},"customWidth":"100","name":"teams imp tiles","styleSettings":{"margin":"10px","padding":"10px"},"id":"e37f94d5-9bcc-432e-aa66-25831603c228"},{"type":1,"content":{"json":"### Impersonation over time, by type<br>

**Trend of Brand, User, and Domain impersonation detections. A spike in a single type often marks the start of a targeted campaign.**"},"customWidth":"100","name":"teams imp trend header","id":"09907f5b-5c20-4a7e-86d3-c89153c4df98"},{"type":3,"content":{"version":"KqlItem/1.0","query":"let imp = CloudAppEvents
| where ActionType == "TeamsImpersonationDetected"
| extend RD = parse_json(RawEventData)
| extend ImpersonationType = tostring(RD.ImpersonationType),
         FakeDisplayName   = tostring(RD.Sender.DisplayName),
         FakeSenderAddress = tostring(RD.Sender.UPN),
         ChatThreadId      = tostring(RD.ChatThreadId),
         TargetUser        = tostring(RD.UserId)
| extend FakeSenderDomain = tostring(split(FakeSenderAddress, "@")[1]);
imp | summarize Count=count() by ImpersonationType, Timestamp=bin(Timestamp, {Granularity}) | sort by Timestamp asc","size":0,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"linechart","chartSettings":{"xAxis":"Timestamp"}},"customWidth":"100","name":"teams imp trend","id":"757204b1-e900-4217-a2ff-2224a033fdcc"},{"type":1,"content":{"json":"### Suspicious external senders (impersonation and throwaway tenants)<br>
**External Microsoft Teams senders flagged as likely impersonation: throwaway `.onmicrosoft.com` tenants and/or help desk, IT support, security, admin, or account/update-themed display names. Attackers rotate through many such identities (for example numbered `ithelpdesk<n>@...` addresses) from newly-created or consumer tenants to pose as internal support, frequently before the Defender impersonation detector assigns a verdict. This heuristic complements that detector.**<br><br>**Recommended action:** Review high threat-rate senders, block the sending domains, and remind users that genuine IT support does not cold-contact them from an external tenant; verify any such request through a known internal channel."},"customWidth":"100","name":"teams susp senders header","id":"5df4af86-49e9-4fc7-b6ad-76d3ef3f7da6"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//External Teams senders flagged as likely impersonation: throwaway .onmicrosoft.com tenants and/or help desk / IT / admin / update-themed display names, ranked by messages carrying a threat.
MessageEvents
| where IsExternalThread == true
| extend SenderDomain = tolower(tostring(split(SenderEmailAddress, "@")[1]))
| extend IsOnMicrosoft = SenderDomain endswith ".onmicrosoft.com"
| extend SuspName = SenderDisplayName matches regex @"(?i)help ?desk|helpdesk|it ?support|service ?desk|it team|administrator|sys ?admin|security|microsoft|maintenance|support|update|verif|account|password|mfa"
| where IsOnMicrosoft or SuspName
| summarize TeamsMessages = count(), ThreatMessages = countif(isnotempty(ThreatTypes)), FirstSeen = min(Timestamp), LastSeen = max(Timestamp) by SenderDisplayName, SenderEmailAddress, SenderDomain, IsOnMicrosoft, SuspName
| extend WhyFlagged = case(IsOnMicrosoft and SuspName, "Throwaway .onmicrosoft tenant + helpdesk-style name", IsOnMicrosoft, "Throwaway .onmicrosoft tenant", "Helpdesk / IT-style display name")
| extend ThreatPct = round(todouble(ThreatMessages) * 100 / TeamsMessages, 1)
| project ['Sender Display Name']=SenderDisplayName, ['Sender Address']=SenderEmailAddress, ['Why Flagged']=WhyFlagged, ['Teams Messages']=TeamsMessages, ['Threat Messages']=ThreatMessages, ['Threat %']=ThreatPct, ['First Seen']=FirstSeen, ['Last Seen']=LastSeen
| sort by ['Threat Messages'] desc, ['Teams Messages'] desc
| take 10","size":0,"title":"","timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"table","gridSettings":{"filter":true,"formatters":[{"columnMatch":"Teams Messages","formatter":3,"formatOptions":{"palette":"blue","customColumnWidthSetting":"130px"},"numberFormat":{"unit":17,"options":{"style":"decimal","maximumFractionDigits":1}}},{"columnMatch":"Threat Messages","formatter":3,"formatOptions":{"palette":"redDark","customColumnWidthSetting":"130px"},"numberFormat":{"unit":17,"options":{"style":"decimal","maximumFractionDigits":1}}},{"columnMatch":"Threat %","formatter":4,"formatOptions":{"palette":"red","min":0,"max":100},"numberFormat":{"unit":1,"options":{"style":"decimal","maximumFractionDigits":1}}}]},"showAnalytics":true},"customWidth":"100","name":"teams susp senders table","id":"dd1d79d8-f591-4aae-bd44-6ad23a3e0ae4"},{"type":1,"content":{"json":"### Who is being targeted<br>

**Internal users receiving the most impersonation attempts. Concentrated targeting of a few users is a strong signal of a deliberate campaign - prioritize these users for security awareness training.**"},"customWidth":"100","name":"teams imp targets header","id":"43112ad1-ebc9-42fb-9ebd-0dbaa862ed45"},{"type":3,"content":{"version":"KqlItem/1.0","query":"let imp = CloudAppEvents
| where ActionType == "TeamsImpersonationDetected"
| extend RD = parse_json(RawEventData)
| extend ImpersonationType = tostring(RD.ImpersonationType),
         FakeDisplayName   = tostring(RD.Sender.DisplayName),
         FakeSenderAddress = tostring(RD.Sender.UPN),
         ChatThreadId      = tostring(RD.ChatThreadId),
         TargetUser        = tostring(RD.UserId)
| extend FakeSenderDomain = tostring(split(FakeSenderAddress, "@")[1]);
imp | summarize Detections=count(), ['Distinct Fake Senders']=dcount(FakeSenderAddress), Types=make_set(ImpersonationType,3), ['Last Seen']=max(Timestamp) by ['Targeted User']=TargetUser | top 10 by Detections","size":3,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"table","gridSettings":{"filter":true}},"customWidth":"100","name":"teams imp targets","id":"cc4b3f98-bfcb-4741-9abb-9ff099eb946f"},{"type":1,"content":{"json":"### Impersonating senders<br>

**The identities behind the impersonation, grouped by fake display name, sender domain, and type. Attackers rotate through many sending addresses under a single display name - Distinct Sender Addresses exposes that rotation, and a high count is itself a strong bulk-campaign signal. Use First/Last Seen to scope the campaign window.**"},"customWidth":"100","name":"teams imp senders header","id":"99859796-7b69-42e7-a27a-541e0ba86cb2"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query lists the identities behind Teams impersonation, grouped by the fake display name, sender domain, and impersonation type. Attackers rotate through many sending addresses under one display name, so Distinct Sender Addresses reveals bulk campaigns that per-address ranking would hide.
let imp = CloudAppEvents
| where ActionType == "TeamsImpersonationDetected"
| extend RD = parse_json(RawEventData)
| extend ImpersonationType = tostring(RD.ImpersonationType),
         FakeDisplayName   = tostring(RD.Sender.DisplayName),
         FakeSenderAddress = tostring(RD.Sender.UPN),
         TargetUser        = tostring(RD.UserId)
| extend FakeSenderDomain = tostring(split(FakeSenderAddress, "@")[1]);
imp
| summarize Detections=count(), SenderAddresses=dcount(FakeSenderAddress), Targets=dcount(TargetUser), FirstSeen=min(Timestamp), LastSeen=max(Timestamp) by FakeDisplayName, FakeSenderDomain, ImpersonationType
| top 10 by Detections
