**URL domains that appeared in messages sent by impersonating senders. Threat actors deliberately mix legitimate domains (for example microsoft.com or google.com) with their malicious ones to make the lure look trustworthy, so treat this as a review list - not a blocklist. Investigate the unfamiliar or look-alike domains and block only those you confirm malicious; never block a well-known legitimate domain from this list.**"},"customWidth":"100","name":"teams imp ioc header","id":"d5f4886c-7c7e-4c6f-94ca-569cabda5ede"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query lists URL domains that appeared in messages sent by impersonating senders, with a breakdown of how many carried Malware, Phish, or Spam verdicts. Threat actors mix legitimate and malicious domains in a single lure, so review the unfamiliar or look-alike domains and block only confirmed-malicious ones.
let imp = CloudAppEvents
| where ActionType == "TeamsImpersonationDetected"
| extend RD = parse_json(RawEventData)
| extend ChatThreadId = tostring(RD.ChatThreadId);
let impThreads = imp | distinct ChatThreadId;
let impMsgs = MessageEvents
    | where ThreadId in (impThreads)
    | summarize arg_max(Timestamp, *) by TeamsMessageId
    | project TeamsMessageId, ThreatTypes;
MessageUrlInfo
| where isnotempty(UrlDomain)
| join kind=inner (impMsgs) on TeamsMessageId
| summarize ['URL Count']=count(), Messages=dcount(TeamsMessageId), Malware=countif(ThreatTypes has "Malware"), Phish=countif(ThreatTypes has "Phish"), Spam=countif(ThreatTypes has "Spam") by ['URL Domain']=UrlDomain
