<tr>
<td style="text-align:left; border:none; font-size:20px; font-weight:bold;color:white;width:1%">Malicious URLs and Link Warnings in Teams
</td>
</tr>
</table>

Tracks URLs shared through Microsoft Teams, messages that triggered a Microsoft Defender for Office 365 URL safety-tip warning, and the outcome of Teams URL clicks (allowed versus blocked) captured in UrlClickEvents.<br><br>**Recommended action:** Enable Safe Links for Microsoft Teams so links are checked at click time, and prioritize *User clicked a malicious link in Teams chat* alerts for investigation. Treat a blocked click as an attempted compromise: check whether the user went on to share credentials or run a file, and reset credentials where warranted."},"name":"teams url banner","id":"e3ec4d65-8d1f-4303-bd8f-eb1ae521da41"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query surfaces Microsoft Teams URL-sharing and link-warning metrics for the selected period. URL-warning messages carry the Microsoft Defender for Office 365 URL safety tip.
let msgs = materialize(MessageEvents | summarize arg_max(Timestamp, *) by TeamsMessageId);
union
(msgs | where SafetyTip == "URLMessageWarning" | summarize Count = count() | extend Details = "Messages with URL Warning", Ord = 1),
(MessageUrlInfo | summarize Count = count() | extend Details = "URLs Shared in Messages", Ord = 2),
(MessageUrlInfo | summarize Count = dcount(TeamsMessageId) | extend Details = "Messages Containing URLs", Ord = 3),
(MessageUrlInfo | summarize Count = dcount(UrlDomain) | extend Details = "Distinct URL Domains", Ord = 4)
| sort by Ord asc
| project Count, Details","size":3,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"tiles","tileSettings":{"titleContent":{"columnMatch":"Details","formatter":1},"secondaryContent":{"columnMatch":"Count","formatter":12,"formatOptions":{"min":0,"palette":"blue"},"numberFormat":{"unit":17,"options":{"style":"decimal","maximumFractionDigits":1}}},"showBorder":true,"size":"full"}},"customWidth":"100","name":"teams url tiles","styleSettings":{"margin":"10px","padding":"10px"},"id":"b71382c7-c0f7-4f9d-9d21-e0a8bf9504ff"},{"type":1,"content":{"json":"### Teams URL click outcomes over time<br>

**Allowed versus blocked Microsoft Teams URL clicks (per selected interval) from UrlClickEvents where the click happened in the Teams workload.**"},"customWidth":"66","name":"teams click trend header","styleSettings":{"margin":"10px","padding":"0px"},"id":"30818e0d-6c4b-4868-896a-ac48cb3cef86"},{"type":1,"content":{"json":"### Click outcomes<br>

**Distribution of Microsoft Teams URL click actions by type.**"},"customWidth":"33","name":"teams click pie header","styleSettings":{"margin":"10px","padding":"0px"},"id":"5a882138-2241-4527-80b8-9983c5807050"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query visualises Microsoft Teams URL click outcomes over time (allowed vs blocked) using the UrlClickEvents workload filter, summarizing the data per selected interval.
let gran = {Granularity};
let minTime = toscalar(UrlClickEvents | summarize min(Timestamp));
let maxTime = toscalar(UrlClickEvents | summarize max(Timestamp));
let agg = materialize(UrlClickEvents
| where Workload == "Teams"
| summarize ClickAllowed = countif(ActionType has "ClickAllowed"), ClickBlocked = countif(ActionType has "ClickBlocked") by Timestamp = bin(Timestamp, gran));
range Timestamp from bin(minTime, gran) to bin(maxTime, gran) step gran
| join kind=leftouter (agg) on Timestamp
| project Timestamp, ClickAllowed = coalesce(ClickAllowed, 0), ClickBlocked = coalesce(ClickBlocked, 0)
| sort by Timestamp asc","size":0,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"linechart","chartSettings":{"xAxis":"Timestamp"}},"customWidth":"66","name":"teams click trend","styleSettings":{"margin":"10px","padding":"10px"},"id":"7a2f5559-1e3e-412a-addf-c3bf6be98502"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query shows Microsoft Teams URL click outcomes by action type for the selected period.
UrlClickEvents
| where Workload == "Teams"
| where isnotempty(ActionType)
| summarize Count = count() by ActionType","size":3,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"piechart"},"customWidth":"33","name":"teams click pie","styleSettings":{"margin":"10px","padding":"10px"},"id":"889c6bb3-438b-4575-84f2-084c1b5fd1f4"},{"type":1,"content":{"json":"### Top domains shared in Teams messages<br>

**The 10 most-shared URL domains in Microsoft Teams messages, with the number of messages each appeared in.**"},"customWidth":"100","name":"teams top domains header","id":"dcb8c87c-087e-4d69-b7b7-0329296293ff"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query lists the top 10 URL domains shared in Microsoft Teams messages by volume for the selected period.
MessageUrlInfo
| where isnotempty(UrlDomain)
| summarize UrlCount = count(), Messages = dcount(TeamsMessageId) by UrlDomain
| top 10 by UrlCount
| project ['URL Domain']=UrlDomain, ['URLs Shared']=UrlCount, ['Messages']=Messages","size":3,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"table","gridSettings":{"formatters":[{"columnMatch":"URLs Shared","formatter":3,"formatOptions":{"palette":"redDark"},"numberFormat":{"unit":17,"options":{"style":"decimal"}}}],"filter":true}},"customWidth":"100","name":"teams top domains table","id":"7561adb0-1fbe-41ce-a924-a27bcd4c5c12"}]},"conditionalVisibility":{"parameterName":"Tab","comparison":"isEqualTo","value":"14"},"name":"group - Teams Malicious URLs","styleSettings":{"margin":"10px","padding":"10px","showBorder":true},"id":"6d47c309-be9e-4b21-940e-7c7b282e5dc2"},{"type":12,"content":{"version":"NotebookGroup/1.0","groupType":"editable","items":[{"type":1,"content":{"json":"<table style="width:100%; border-collapse:collapse; border:none;background-color:#003366;">
<tr>
<td style="text-align:left; border:none; font-size:20px; font-weight:bold;color:white;width:1%">Targeted Users &amp; Risky Senders
</td>
</tr>
</table>

Identifies who is most targeted in Microsoft Teams, and profiles the external senders and domains behind risky messages - URL safety-tip warnings, first-contact senders, threat-carrying domains, and low-reputation link infrastructure - so you can spot anomalous senders before they succeed.<br><br>**Recommended action:** Prioritize the most-targeted users for phishing-resistant MFA and awareness coaching, and treat first-contact external senders and low-reputation domains as IOCs. Restrict inbound chat from unmanaged and consumer tenants, and allowlist only trusted external domains so unsolicited outsiders cannot start a conversation."},"name":"teams risky banner","id":"0aa13d73-2e13-487c-a7c4-d90464a554d4"},{"type":1,"content":{"json":"### Top targeted users (messages with threats)<br>

**The 10 users receiving the most Microsoft Teams messages that contained a threat, expanded from each message recipient list.**"},"customWidth":"100","name":"teams targeted header","id":"827dc0f6-2bb2-49b9-acf8-d7b400238594"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query lists the top 10 users receiving Microsoft Teams messages that contained a threat, expanded from the message recipient list, with each user's total Teams messages received and the share that carried a threat. Messages are de-duplicated to the latest record per message.
let expanded = MessageEvents
    | summarize arg_max(Timestamp, *) by TeamsMessageId
    | mv-expand rd = parse_json(RecipientDetails)
    | extend Recipient = tostring(rd.RecipientSmtpAddress)
    | where isnotempty(Recipient);
let totals = expanded | summarize TotalMessages = count() by Recipient;
expanded
| where isnotempty(ThreatTypes)
| summarize ThreatMessages = count() by Recipient
| join kind=leftouter (totals) on Recipient
| extend ThreatPct = round(100.0 * ThreatMessages / TotalMessages, 1)
| top 10 by ThreatMessages
| project ['Recipient']=Recipient, ['Threat Messages']=ThreatMessages, ['Total Messages']=TotalMessages, ['Threat %']=ThreatPct","size":3,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"table","gridSettings":{"formatters":[{"columnMatch":"Threat Messages","formatter":3,"formatOptions":{"palette":"redDark"},"numberFormat":{"unit":17,"options":{"style":"decimal"}}}],"filter":true}},"customWidth":"100","name":"teams targeted users table","id":"79481d1b-617e-46df-b555-9f7240932dd0"},{"type":1,"content":{"json":"### Top senders of URL-warning messages<br>

**Senders whose Microsoft Teams messages most often triggered a URL safety-tip warning.**"},"customWidth":"50","name":"teams warn senders header","styleSettings":{"margin":"10px","padding":"0px"},"id":"ef71d7dd-4442-4992-977d-d550aad4533c"},{"type":1,"content":{"json":"### Top domains in URL-warning messages<br>

**URL domains most frequently present in Microsoft Teams messages that triggered a URL safety-tip warning.**"},"customWidth":"50","name":"teams warn domains header","styleSettings":{"margin":"10px","padding":"0px"},"id":"6f41a4ba-f832-4947-ad27-cd6b8015bd63"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query lists the top 10 senders whose Microsoft Teams messages triggered a URL safety-tip warning for the selected period, with each sender's total Teams messages and the share that carried a warning. Messages are de-duplicated to the latest record per message.
let dedup = MessageEvents | summarize arg_max(Timestamp, *) by TeamsMessageId;
let totals = dedup | summarize TotalMessages = count() by SenderEmailAddress;
dedup
| where SafetyTip == "URLMessageWarning"
| summarize WarningMessages = count() by SenderEmailAddress
| join kind=leftouter (totals) on SenderEmailAddress
| extend WarningPct = round(100.0 * WarningMessages / TotalMessages, 1)
| top 10 by WarningMessages
| project ['Sender']=SenderEmailAddress, ['Warning Messages']=WarningMessages, ['Total Messages']=TotalMessages, ['Warning %']=WarningPct","size":3,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"table","gridSettings":{"formatters":[{"columnMatch":"Warning Messages","formatter":3,"formatOptions":{"palette":"redDark"},"numberFormat":{"unit":17,"options":{"style":"decimal"}}}],"filter":true}},"customWidth":"50","name":"teams warn senders table","styleSettings":{"margin":"10px","padding":"10px"},"id":"3fa023af-79e3-407f-ac20-b0aa6e3ba511"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query lists the top 10 URL domains appearing in Microsoft Teams messages that triggered a URL safety-tip warning, with the domain's total message appearances and the share that carried a warning.
let warned = MessageEvents | where SafetyTip == "URLMessageWarning" | distinct TeamsMessageId;
let totals = MessageUrlInfo | where isnotempty(UrlDomain) | summarize TotalMessages = dcount(TeamsMessageId) by UrlDomain;
MessageUrlInfo
| where TeamsMessageId in (warned)
| summarize WarningMessages = dcount(TeamsMessageId) by UrlDomain
| join kind=leftouter (totals) on UrlDomain
| extend WarningPct = round(100.0 * WarningMessages / TotalMessages, 1)
| top 10 by WarningMessages
| project ['URL Domain']=UrlDomain, ['Warning Messages']=WarningMessages, ['Total Messages']=TotalMessages, ['Warning %']=WarningPct","size":3,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"table","gridSettings":{"formatters":[{"columnMatch":"Warning Messages","formatter":3,"formatOptions":{"palette":"redDark"},"numberFormat":{"unit":17,"options":{"style":"decimal"}}}],"filter":true}},"customWidth":"50","name":"teams warn domains table","styleSettings":{"margin":"10px","padding":"10px"},"id":"68811015-1383-48ad-86da-4f8f9d39e4c4"},{"type":1,"content":{"json":"### First-contact external senders<br>

**External Microsoft Teams senders ordered by when they were first seen in the period (most recent first). Note: some flows tag internal-domain senders as external - to hide your own tenant domains, edit the query and uncomment the ExcludeDomains filter.**"},"customWidth":"100","name":"teams fc senders header","id":"0f131ff3-d6b2-4187-b86c-ca3493594b54"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query lists external Microsoft Teams senders by the date they were first seen in the selected period, surfacing recent first-contact senders. Messages are de-duplicated to the latest record per message. In tenants with longer history this highlights genuinely new senders.
// TIP: IsExternalThread may still surface senders from your own accepted domains. To hide them,
// uncomment the ExcludeDomains line below (add your tenant domains) and the matching where-clause.
//let ExcludeDomains = dynamic(["contoso.com","contoso.com"]);
MessageEvents
| summarize arg_max(Timestamp, *) by TeamsMessageId
| where IsExternalThread == true
//| where tostring(split(SenderEmailAddress, "@")[1]) !in~ (ExcludeDomains)
| summarize FirstSeen = min(Timestamp), Messages = count(), ThreatMessages = countif(isnotempty(ThreatTypes)) by SenderEmailAddress
| top 10 by FirstSeen desc
| project ['Sender']=SenderEmailAddress, ['First Seen']=FirstSeen, ['Messages']=Messages, ['Threat Messages']=ThreatMessages","size":3,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"table","gridSettings":{"formatters":[{"columnMatch":"Threat Messages","formatter":3,"formatOptions":{"palette":"redDark"},"numberFormat":{"unit":17,"options":{"style":"decimal"}}}],"filter":true,"sortBy":[{"itemKey":"Threat Messages","sortOrder":2}]}},"customWidth":"100","name":"teams fc senders table","id":"4e10a78d-8858-4dbb-9db0-e7b7d7e7636c"},{"type":1,"content":{"json":"### External sender-domain risk<br>

**External sending domains ranked by threat volume, with the mix of conversation types (1:1 chat, group chat, channel), threat breakdown, threat rate, count of messages carrying low-reputation URLs (domains on commonly-abused TLDs such as .xyz, .top, .click, .shop, .zip), and first/last-seen. A domain that is new in the period, skews toward 1:1 chats, or shows a high threat rate is anomalous and warrants review. Note: to exclude your own tenant domains, edit the query and uncomment the ExcludeDomains filter.**"},"customWidth":"100","name":"teams anomaly header","id":"a91295db-8192-4828-93c5-408436e4b0e1"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query ranks external sender domains in Microsoft Teams by threat volume for the selected period, split by conversation type (1:1 chat, group chat, channel), with threat-type breakdown, threat rate, and a count of messages carrying low-reputation URL TLDs. Messages are de-duplicated to the latest record per message. New, 1:1-skewed, or high-threat-rate domains are the anomalies to review.
// TIP: IsExternalThread may still surface your own accepted domains. To hide them, uncomment the
// ExcludeDomains line below (add your tenant domains) and the matching where-clause.
//let ExcludeDomains = dynamic(["contoso.com","contoso.com"]);
let suspTlds = dynamic(["top","xyz","click","link","shop","online","site","live","icu","cyou","sbs","rest","quest","cfd","bond","buzz","fun","space","monster","work","tk","ml","ga","cf","gq","dev","app","zip","mov","info","win","loan","men","stream","country"]);
let suspUrlMsgs = MessageUrlInfo
    | where isnotempty(UrlDomain)
    | extend Tld = tostring(split(UrlDomain, ".")[-1])
    | where Tld in (suspTlds)
    | distinct TeamsMessageId;
MessageEvents
| summarize arg_max(Timestamp, *) by TeamsMessageId
| where IsExternalThread == true
| extend SenderDomain = tostring(split(SenderEmailAddress, "@")[1])
| where isnotempty(SenderDomain)
//| where SenderDomain !in~ (ExcludeDomains)
| extend ConvType = case(isnotempty(GroupId), "Channel", array_length(todynamic(RecipientDetails)) > 1, "Group chat", "1:1 chat")
| extend HasSuspUrl = TeamsMessageId in (suspUrlMsgs)
| summarize Messages=count(), Senders=dcount(SenderEmailAddress), OneToOne=countif(ConvType=="1:1 chat"), GroupChat=countif(ConvType=="Group chat"), ChannelMsgs=countif(ConvType=="Channel"), ThreatMessages=countif(isnotempty(ThreatTypes)), Malware=countif(ThreatTypes has "Malware"), Phish=countif(ThreatTypes has "Phish"), Spam=countif(ThreatTypes has "Spam"), SuspUrlMsgs=countif(HasSuspUrl), FirstSeen=min(Timestamp), LastSeen=max(Timestamp) by SenderDomain
| where ThreatMessages > 0
| extend ThreatRatePct = round(100.0 * ThreatMessages / Messages, 1)
| top 10 by ThreatMessages desc
| project ['Sender Domain']=SenderDomain, Messages, Senders, ['1:1']=OneToOne, ['Group']=GroupChat, ['Channel']=ChannelMsgs, ['Threat Msgs']=ThreatMessages, Malware, Phish, Spam, ['Threat Rate %']=ThreatRatePct, ['Low-Rep URL Msgs']=SuspUrlMsgs, ['First Seen']=FirstSeen, ['Last Seen']=LastSeen","size":3,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"table","gridSettings":{"formatters":[{"columnMatch":"Threat Messages","formatter":3,"formatOptions":{"palette":"redDark"},"numberFormat":{"unit":17,"options":{"style":"decimal"}}}],"filter":true}},"customWidth":"100","name":"teams anomaly table","id":"bcd6746d-8298-495d-9d6c-2fadc6cba569"},{"type":1,"content":{"json":"### Suspicious new senders (no threat verdict yet)<br>

**External sending domains with no threat verdict yet, but that are either sending low-reputation-URL messages or showing unusual volume. These slip past threat filters - watch for new domains skewing toward 1:1 chats, an early social-engineering signal. Note: to exclude your own tenant domains, edit the query and uncomment the ExcludeDomains filter.**"},"customWidth":"100","name":"teams newdom header","id":"9e3844f4-befc-4b76-a8cd-ca53fdf51d41"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query surfaces external sender domains in Microsoft Teams that have NO threat verdict yet but are sending messages with low-reputation URL TLDs or unusual volume, split by conversation type. These are early-warning senders that have not tripped a detection. Messages are de-duplicated to the latest record per message.
// TIP: IsExternalThread may still surface your own accepted domains. To hide them, uncomment the
// ExcludeDomains line below (add your tenant domains) and the matching where-clause.
//let ExcludeDomains = dynamic(["contoso.com","contoso.com"]);
let suspTlds = dynamic(["top","xyz","click","link","shop","online","site","live","icu","cyou","sbs","rest","quest","cfd","bond","buzz","fun","space","monster","work","tk","ml","ga","cf","gq","dev","app","zip","mov","info","win","loan","men","stream","country"]);
let suspUrlMsgs = MessageUrlInfo
    | where isnotempty(UrlDomain)
    | extend Tld = tostring(split(UrlDomain, ".")[-1])
    | where Tld in (suspTlds)
    | distinct TeamsMessageId;
MessageEvents
| summarize arg_max(Timestamp, *) by TeamsMessageId
| where IsExternalThread == true
| extend SenderDomain = tostring(split(SenderEmailAddress, "@")[1])
| where isnotempty(SenderDomain)
//| where SenderDomain !in~ (ExcludeDomains)
| extend ConvType = case(isnotempty(GroupId), "Channel", array_length(todynamic(RecipientDetails)) > 1, "Group chat", "1:1 chat")
