This section provides insights into email message **False Negative(FN) Submissions performed by administrators** in Microsoft Defender for Office 365 where the message reported to have Malware, Phish or Spam threat within its content, URLs or attachments.<br><br>**Recommended action:** Prioritise admin-submitted misses for policy tuning; recurring sender domains may be block-list candidates."},"name":"fn admin - section header","id":"64420254-0dae-4495-bd55-fc49e5bc1ed0"},{"type":1,"content":{"json":"### False Negative(FN) Admin Submissions per-{Granularity} trend by submission types 
**Displays counts (per {Granularity}) of False Negative(FN) Admin Submissions grouped by submission type (Spam, Phish, Malware) and content type (Mail, URL, Attachment). Helps to monitor where detections were missed and later submitted by admins as false negatives to Microsoft.**"},"name":"fn admin - trend heading","id":"5f2de929-6f32-4079-a031-cbf689c15b29"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query visualises the daily ammount of admin false negative submission by submission type.
let gran = {Granularity};
let minTime = toscalar(EmailEvents | summarize min(Timestamp));
let maxTime = toscalar(EmailEvents | summarize max(Timestamp));
let agg = materialize(CloudAppEvents
| where ActionType contains "Submission"
| extend SubmissionType = tostring((parse_json(RawEventData)).SubmissionType),SubmissionContentType=tostring((parse_json(RawEventData)).SubmissionContentType)
| summarize Admin_Malware_FN=countif(SubmissionType == "2" and ActionType == "AdminSubmissionSubmitted" and SubmissionContentType=="Mail"), Admin_Phish_FN=countif(SubmissionType == "1" and ActionType == "AdminSubmissionSubmitted" and SubmissionContentType=="Mail"), Admin_Spam_FN=countif(SubmissionType == "0" and ActionType == "AdminSubmissionSubmitted" and SubmissionContentType=="Mail"), Admin_Malware_URL_FN=countif(SubmissionType == "2" and ActionType == "AdminSubmissionSubmitted" and SubmissionContentType=="URL"), Admin_Malware_Attach_FN=countif(SubmissionType == "2" and ActionType == "AdminSubmissionSubmitted" and SubmissionContentType=="Attachment"), Admin_Phish_URL_FN=countif(SubmissionType == "1" and ActionType == "AdminSubmissionSubmitted" and SubmissionContentType=="URL"), Admin_Phish_Attach_FN=countif(SubmissionType == "1" and ActionType == "AdminSubmissionSubmitted" and SubmissionContentType=="Attachment") by Timestamp = bin(Timestamp, gran));
range Timestamp from bin(minTime, gran) to bin(maxTime, gran) step gran
| join kind=leftouter (agg) on Timestamp
| project Timestamp, ['Malware (Mail)']=coalesce(Admin_Malware_FN,0), ['Phish (Mail)']=coalesce(Admin_Phish_FN,0), ['Spam (Mail)']=coalesce(Admin_Spam_FN,0), ['Malware (URL)']=coalesce(Admin_Malware_URL_FN,0), ['Malware (Attachment)']=coalesce(Admin_Malware_Attach_FN,0), ['Phish (URL)']=coalesce(Admin_Phish_URL_FN,0), ['Phish (Attachment)']=coalesce(Admin_Phish_Attach_FN,0) | sort by Timestamp asc","size":0,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"linechart","chartSettings":{"seriesLabelSettings":[{"seriesName":"TotalAdminSubmissions","color":"redDark"},{"seriesName":"Phish (Mail)","color":"redBright"},{"seriesName":"Spam (Mail)","color":"orange"},{"seriesName":"Malware (Mail)","color":"redDark"},{"seriesName":"Phish (URL)","color":"purple"},{"seriesName":"Malware (Attachment)","color":"yellowDark"},{"seriesName":"Phish (Attachment)","color":"purpleDark"},{"seriesName":"Malware (URL)","color":"yellow"}]}},"name":"fn admin - submissions trend","id":"1b61155b-92a1-4533-9561-2e85e9a4dbf8"},{"type":1,"content":{"json":"### False Negative(FN) Admin Submissions by submission types 
**Displays counts (per {Granularity}) of False Negative(FN) Admin Submissions grouped by submission type (Spam, Phish, Malware) and content type (Mail, URL, Attachment).**"},"customWidth":"50","name":"fn admin - by-type heading","id":"bbaa9ff9-a95d-495a-a44c-6b4cae888a24"},{"type":1,"content":{"json":"### False Negative(FN) Admin Submissions by submission State
**Displays the total count of False Negative(FN) Admin Submissions by submission State (e.g., Pending, Completed, Failed). Helps track the processing status of admin submissions and identify bottlenecks or errors.**"},"customWidth":"50","name":"fn admin - by-state heading","id":"b060c706-342a-4b2e-b81a-920bf4d8c5d9"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query visualises the total ammount of admin false negative submission by submission type.
CloudAppEvents 
| where ActionType contains "Submission"
| extend SubmissionType = tostring((parse_json(RawEventData)).SubmissionType),SubmissionContentType=tostring((parse_json(RawEventData)).SubmissionContentType)
| extend Admin_SubmissionType=
iff(SubmissionType == "2" and ActionType == "AdminSubmissionSubmitted" and SubmissionContentType=="Mail","Malware (Mail)",
iff(SubmissionType == "1" and ActionType == "AdminSubmissionSubmitted" and SubmissionContentType=="Mail","Phish (Mail)",
iff(SubmissionType == "0" and ActionType == "AdminSubmissionSubmitted" and SubmissionContentType=="Mail","Spam (Mail)",
iff(SubmissionType == "2" and ActionType == "AdminSubmissionSubmitted" and SubmissionContentType=="URL","Malware (URL)",
iff(SubmissionType == "2" and ActionType == "AdminSubmissionSubmitted" and SubmissionContentType=="Attachment","Malware (Attachment)",
iff(SubmissionType == "1" and ActionType == "AdminSubmissionSubmitted" and SubmissionContentType=="URL","Phish (URL)",
iff(SubmissionType == "1" and ActionType == "AdminSubmissionSubmitted" and SubmissionContentType=="Attachment","Phish (Attachment)",
"Other")))))))
| where Admin_SubmissionType!="Other"
| summarize count() by Admin_SubmissionType","size":3,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"piechart","chartSettings":{"createOtherGroup":10}},"customWidth":"50","name":"fn admin - by-type pie","styleSettings":{"margin":"10px","padding":"10px"},"id":"9d9d714a-357b-4ac3-bcb7-33601d3c3108"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query visualises the total ammount of admin false negative submissions by the state of the submission.
CloudAppEvents 
| where ActionType contains "AdminSubmission" 
| extend Record = (parse_json(RawEventData)).RecordType,SubmissionState = parse_json(RawEventData).SubmissionState,SubmissionId=parse_json(RawEventData).SubmissionId,SubmissionType = parse_json(RawEventData).SubmissionType,SubmissionContentType=tostring((parse_json(RawEventData)).SubmissionContentType)
| where Record == 29 and SubmissionType in ("0","1","2")
| summarize count() by tostring(SubmissionState)","size":3,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"piechart"},"customWidth":"50","name":"fn admin - by-state pie","styleSettings":{"margin":"10px","padding":"10px"},"id":"169f0f1c-1f1e-44fb-965e-850733f01879"},{"type":1,"content":{"json":"### False Negative(FN)/False Positive(FP) Admin Submissions by Triage Verdict
**Displays the total count of False Negative(FN)/False Positive(FP) Admin Submissions grouped by TriageVerdict (e.g., Malware, Spam, Phish, Clean). Helps assess how submissions were graded during triage and identify detection gaps.**"},"customWidth":"50","name":"fn admin - triage-verdict heading","id":"3df841be-c1b0-4d61-8e38-316a34a48bd1"},{"type":1,"content":{"json":"### Top Admins Submitting False Negatives 
**Displays the top 15 admin accounts that submitted the highest number of false negative messages (missed detections) via AdminSubmission. Helps identify key contributors to threat remediation and potential patterns in detection gaps.**"},"customWidth":"50","name":"fn admin - top-admins heading","id":"e1e966f4-1f4d-4377-97c6-e2077fc0b8fa"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query visualises the total ammount of admin false negative or false positive submissions by the verdict of the submission grading.
CloudAppEvents 
| where ActionType contains "AdminSubmissionTriage" 
| extend UserKey = (parse_json(RawEventData)).UserKey, SubmissionState = (parse_json(RawEventData)).SubmissionState,  SubmissionId=(parse_json(RawEventData)).SubmissionId, TriageVerdict=(parse_json(RawEventData)).GradingResult.TriageVerdict 
| summarize count() by tostring(TriageVerdict)","size":3,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"piechart"},"customWidth":"50","name":"fn admin - triage-verdict pie","styleSettings":{"margin":"10px","padding":"10px"},"id":"6df0db72-f9db-444e-856a-4369921d199b"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query visualises the top admins performing false negative submissions
CloudAppEvents 
| where ActionType == "AdminSubmissionSubmitted" 
| extend Record= (parse_json(RawEventData)).RecordType,SubmissionState = (parse_json(RawEventData)).SubmissionState, UserId = (parse_json(RawEventData)).UserId,SubmissionType = parse_json(RawEventData).SubmissionType  
| where Record == 29 and SubmissionType in ("0","1","2")
| summarize ['Submissions']=count() by ['Admin']=tostring(UserId)
| top 15 by ['Submissions'] desc","size":3,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"table","gridSettings":{"formatters":[{"columnMatch":"Submissions","formatter":3,"formatOptions":{"palette":"redDark","customColumnWidthSetting":"16ch"},"numberFormat":{"unit":17,"options":{"style":"decimal"}}}],"filter":true}},"customWidth":"50","name":"fn admin - top-admins pie","id":"b5ccb4a1-9783-47cf-bf21-ded924f1a200"},{"type":1,"content":{"json":"### False Negative(FN) Admin Submissions by Top Sender Domains
**For each top sender domain that admins reported missed threats for, shows the domain's MDO-detected threat profile (emails with threats and the Malware/Phish/Spam breakdown), the count of admin FN submissions, and the submission rate (Admin Submission % = admin submissions / total inbound from the domain). A high rate can flag a domain whose mail is frequently reported as missed.**"},"customWidth":"100","name":"fn admin - top-sender-domains heading","id":"1a481c97-ac85-4b62-a86d-51b33b5a8e68"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//Top 10 sender domains that admins reported false negatives (missed threats) for, with each domain's MDO-detected threat profile for context.
let subs = CloudAppEvents
| where ActionType == "AdminSubmissionSubmitted"
| extend SubmissionType = tostring((parse_json(RawEventData)).SubmissionType), SubmissionContentType=tostring((parse_json(RawEventData)).SubmissionContentType), P2SenderDomain=tostring((parse_json(RawEventData)).P2SenderDomain)
| where SubmissionContentType == "Mail" and SubmissionType in ("2","1","0")
| summarize AdminSubmissions=count() by P2SenderDomain;
let domainProfile = EmailEvents
| where EmailDirection == "Inbound"
| summarize TotalInbound=count(), EmailsWithThreats=countif(isnotempty(ThreatTypes)), Malware=countif(ThreatTypes has "Malware"), Phish=countif(ThreatTypes has "Phish"), Spam=countif(ThreatTypes has "Spam") by SenderFromDomain;
subs
| join kind=leftouter (domainProfile) on $left.P2SenderDomain == $right.SenderFromDomain
| extend AdminSubmissionPct = round(AdminSubmissions * 100.0 / todouble(coalesce(TotalInbound, AdminSubmissions)), 2)
| top 10 by AdminSubmissions desc
| project ['Sender Domain']=P2SenderDomain, ['Emails With Threats']=coalesce(EmailsWithThreats,0), ['Malware']=coalesce(Malware,0), ['Phish']=coalesce(Phish,0), ['Spam']=coalesce(Spam,0), ['Admin Submissions']=AdminSubmissions, ['Admin Submission %']=AdminSubmissionPct","size":0,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"table","gridSettings":{"formatters":[{"columnMatch":"Emails With Threats","formatter":0,"formatOptions":{"customColumnWidthSetting":"130px"},"numberFormat":{"unit":17,"options":{"style":"decimal","maximumFractionDigits":1}}},{"columnMatch":"Malware","formatter":0,"formatOptions":{"customColumnWidthSetting":"90px"},"numberFormat":{"unit":17,"options":{"style":"decimal","maximumFractionDigits":1}}},{"columnMatch":"Phish","formatter":0,"formatOptions":{"customColumnWidthSetting":"90px"},"numberFormat":{"unit":17,"options":{"style":"decimal","maximumFractionDigits":1}}},{"columnMatch":"Spam","formatter":0,"formatOptions":{"customColumnWidthSetting":"90px"},"numberFormat":{"unit":17,"options":{"style":"decimal","maximumFractionDigits":1}}},{"columnMatch":"Admin Submissions","formatter":3,"formatOptions":{"palette":"redDark","customColumnWidthSetting":"120px"},"numberFormat":{"unit":17,"options":{"style":"decimal"}}},{"columnMatch":"Admin Submission %","formatter":4,"formatOptions":{"palette":"red","min":0,"max":20,"customColumnWidthSetting":"110px"},"numberFormat":{"unit":1,"options":{"style":"decimal"}}}],"filter":true}},"customWidth":"100","name":"fn admin - top-sender-domains table","id":"e56bed92-b0fb-4b76-90f3-169f4206418b"},{"type":1,"content":{"json":"### False Negative(FN) Admin Submissions by admin Detection override types
**Displays the top 10 cases where emails were submitted as false negatives by admins, even though they were initially detected by Microsoft Defender for Office 365 but delivered due to an admin policy override. Includes details on PolicyOverride, PolicySource, and DetectionVerdict for deeper insight into override behaviour.**"},"customWidth":"100","name":"fn admin - override-types heading","id":"293c174c-0197-4cf8-bbce-36fe42e5cf1b"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query visualises emails submitted as false negatives by admins where emails where already detected by MDO but there was a admin policy override
CloudAppEvents 
| where ActionType == "AdminSubmissionSubmitted" 
| extend SubmissionType = tostring((parse_json(RawEventData)).SubmissionType),SubmissionContentType=tostring((parse_json(RawEventData)).SubmissionContentType)
| extend Admin_SubmissionType=
iff(SubmissionType == "2" and ActionType == "AdminSubmissionSubmitted" and SubmissionContentType=="Mail","Malware (Mail)",
iff(SubmissionType == "1" and ActionType == "AdminSubmissionSubmitted" and SubmissionContentType=="Mail","Phish (Mail)",
iff(SubmissionType == "0" and ActionType == "AdminSubmissionSubmitted" and SubmissionContentType=="Mail","Spam (Mail)","Other"))),
P2SenderDomain=tostring((parse_json(RawEventData)).P2SenderDomain),NetworkMessageId=tostring((parse_json(RawEventData).ObjectId)),DetectionVerdict=tostring((parse_json(RawEventData)).DeliveryMessageInfo.FinalFilterVerdict),PolicyOverride=tostring((parse_json(RawEventData)).DeliveryMessageInfo.PolicyOverride),PolicyPolicyOverrideType=tostring((parse_json(RawEventData)).DeliveryMessageInfo.PolicySource)
| where SubmissionContentType == "Mail" and SubmissionType in ("2","1","0") and PolicyOverride !="NoOverride"
| summarize count() by PolicyOverride, PolicyPolicyOverrideType,DetectionVerdict,Admin_SubmissionType
| top 10 by count_ desc
| project ['Policy Override']=PolicyOverride, ['Override Source']=PolicyPolicyOverrideType, ['Detection Verdict']=DetectionVerdict, ['Submission Type']=Admin_SubmissionType, ['Emails']=count_","size":0,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"table","gridSettings":{"formatters":[{"columnMatch":"Emails","formatter":3,"formatOptions":{"palette":"redDark","customColumnWidthSetting":"40ch"},"numberFormat":{"unit":17,"options":{"style":"decimal","maximumFractionDigits":1}}}],"filter":true}},"customWidth":"100","name":"fn admin - override-types table","id":"97799422-53e0-4e3b-8103-297fd1c744eb"}]},"conditionalVisibility":{"parameterName":"Tab","comparison":"isEqualTo","value":"8"},"name":"group - 11-Fn Admin Submissions","styleSettings":{"margin":"10px","padding":"10px","showBorder":true},"id":"45a1c185-4fbf-4e83-832e-1f20af427796"},{"type":12,"content":{"version":"NotebookGroup/1.0","groupType":"editable","items":[{"type":1,"content":{"json":"<table style="width:100%; border-collapse:collapse; border:none;background-color:#003366;">
<tr>
