let minTime = toscalar(CloudAppEvents | summarize min(Timestamp));
let maxTime = toscalar(CloudAppEvents | summarize max(Timestamp));
let agg = materialize(CloudAppEvents
| where ActionType contains "Submission"
| extend SubmissionType = tostring((parse_json(RawEventData)).SubmissionType),SubmissionContentType=tostring((parse_json(RawEventData)).SubmissionContentType)
| summarize Admin_Email_FP=countif(SubmissionType == "3" and ActionType == "AdminSubmissionSubmitted" and SubmissionContentType=="Mail"), Admin_URL_FP=countif(SubmissionType == "3" and ActionType == "AdminSubmissionSubmitted" and SubmissionContentType=="URL"), Admin_Attach_FP=countif(SubmissionType == "3" and ActionType == "AdminSubmissionSubmitted" and SubmissionContentType=="Attachment") by Timestamp = bin(Timestamp, gran));
range Timestamp from bin(minTime, gran) to bin(maxTime, gran) step gran
| join kind=leftouter (agg) on Timestamp
