---

This tab provides insights into malicious file detections across Microsoft collaboration platforms such as SharePoint, OneDrive, and Teams.

[<p><b>Safe Attachments for SharePoint, OneDrive, and Microsoft Teams</b></p>](https://learn.microsoft.com/en-us/defender-office-365/safe-attachments-for-spo-odfb-teams-about)
[<p><b>Built-in virus protection in SharePoint, SharePoint Embedded, OneDrive, and Microsoft Teams</b></p>](https://learn.microsoft.com/en-us/defender-office-365/anti-malware-protection-for-spo-odfb-teams-about) "},"conditionalVisibility":{"parameterName":"Tab","comparison":"isEqualTo","value":"9"},"name":"filemal - tab description","styleSettings":{"margin":"10px","padding":"10px"},"id":"cefcac88-f373-4748-b0ea-e7600f63edd7"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//Microsoft Defender for Office 365 value for files in SharePoint / OneDrive / Teams: total files processed, how many had a malware detection, and how many were scanned with no detection. A per-period Trend series feeds the tile sparkline.
let gran = {Granularity};
let base = FileMaliciousContentInfo;
let counts = union
(base | summarize Count = count() | extend Cat = "Total Files Processed (SPO/ODB/Teams)", Ord = 1),
(base | where isnotempty(ThreatTypes) | summarize Count = count() | extend Cat = "Files with Malware Detected", Ord = 2),
(base | where isempty(ThreatTypes) | summarize Count = count() | extend Cat = "Files Scanned - No Detection", Ord = 3);
let tagged = union
(base | extend Cat = "Total Files Processed (SPO/ODB/Teams)"),
(base | where isnotempty(ThreatTypes) | extend Cat = "Files with Malware Detected"),
(base | where isempty(ThreatTypes) | extend Cat = "Files Scanned - No Detection");
let trends = tagged | make-series Trend = count() default = 0 on Timestamp step gran by Cat;
counts
| join kind=leftouter (trends) on Cat
| sort by Ord asc
| project Count, Details = Cat, Trend","size":3,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"tiles","tileSettings":{"titleContent":{"columnMatch":"Details","formatter":1},"leftContent":{"columnMatch":"Count","formatter":12,"formatOptions":{"min":0,"palette":"blue"},"numberFormat":{"unit":17,"options":{"style":"decimal","maximumFractionDigits":1}}},"secondaryContent":{"columnMatch":"Trend","formatter":21,"formatOptions":{"min":0,"palette":"blue"}},"showBorder":true,"size":"auto"}},"customWidth":"100","name":"filemal - MDO value tiles","id":"843e58a9-6324-4a90-a652-bfb0549e79dc","conditionalVisibility":{"parameterName":"Tab","comparison":"isEqualTo","value":"9"}},{"type":12,"content":{"version":"NotebookGroup/1.0","groupType":"editable","items":[{"type":1,"content":{"json":"<table style="width:100%; border-collapse:collapse; border:none;background-color:#003366;">
<tr>
<td style="text-align:left; border:none; font-size:20px; font-weight:bold;color:white;width:1%">File Malware Detection (SharePoint, OneDrive, and Teams)
</td>
</tr>
</table>

This section monitors malware detections in files stored across Microsoft 365 collaboration platforms. Microsoft Defender for Office 365 and built-in SharePoint Online antivirus work together to scan files uploaded to SharePoint, OneDrive, and Teams. Understanding file-based malware patterns helps protect collaborative workspaces and identify potential security risks in shared content.<br><br>**Recommended action:** For repeat file owners or sites, investigate possible compromise and confirm Safe Attachments for SharePoint, OneDrive and Teams is enabled."},"name":"filemal - section header","id":"373fe4e5-fc90-49cf-93ba-c8b100efce57"},{"type":1,"content":{"json":"### File Malware Detection Trend<br>

**This visual tracks the volume (per {Granularity}) of malware detections in files across all Microsoft 365 workloads. Spikes in detection activity may indicate targeted attacks or emerging malware campaigns affecting collaborative platforms. Regular monitoring helps identify unusual patterns that require investigation.**"},"name":"filemal - trend heading","id":"30145585-8998-443a-b6ec-062d136c621f"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query visualises total files located on SharePoint, OneDrive and Teams with Malware detections over time summarizing the data daily.
let gran = {Granularity};
let agg = materialize(FileMaliciousContentInfo
| summarize Count = count() by Timestamp = bin(Timestamp, gran));
range Timestamp from toscalar(agg | summarize min(Timestamp)) to toscalar(agg | summarize max(Timestamp)) step gran
| join kind=leftouter (agg) on Timestamp
| project Timestamp, ['Files']=coalesce(Count, 0)
| sort by Timestamp asc","size":0,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"areachart","tileSettings":{"showBorder":false},"graphSettings":{"type":0},"chartSettings":{"seriesLabelSettings":[{"seriesName":"Files","color":"blueDark"}],"showDataPoints":true}},"customWidth":"100","name":"filemal - detection trend","styleSettings":{"margin":"10px","padding":"10px"},"id":"d39cea9b-75a8-4c29-bfdb-2e0db855e98a"},{"type":1,"content":{"json":"### Malware Family Analysis - Defender for Office 365
**Provides a breakdown of malware detections in files scanned by Microsoft Defender for Office 365 (Safe Attachments detonation) across SharePoint, OneDrive, and Teams. The table lists each malware family with total detections, distinct files, affected locations and when it was last seen, helping identify dominant threats and their spread across collaboration platforms.**"},"customWidth":"100","name":"filemal - family MDO heading","id":"4e330873-f732-4d37-a7b0-dced08b019b0"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query summarizes File malware detections by Microsoft Defender for Office 365 (Safe Attachments detonation) into a per-family table: total detections, distinct files, affected locations (file owner or site) and when the family was last seen.
FileMaliciousContentInfo
| where tostring(DetectionMethods) contains "detonation"
| extend Owner = iff(isnotempty(FileOwnerUpn), FileOwnerUpn, strcat("Site: ", tostring(split(FolderPath, "/")[4])))
| summarize ['Files']=count(), ['Distinct Files']=dcount(SHA256), ['Affected Locations']=dcount(Owner), ['Last Seen']=max(Timestamp) by ThreatNames
| sort by ['Files'] desc
