| project Timestamp, Details, Count = coalesce(Count, 0)
| sort by Details asc, Timestamp asc","size":0,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"linechart"},"customWidth":"100","name":"quarantine - spam trend","styleSettings":{"margin":"10px","padding":"10px"},"id":"5762bcc7-bbda-4a3d-91cf-de18fbdd2775"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query visualises the total ammount of spam emails that are quarantined, summarized by the detection method
