**This visual displays the average time, in minutes, to close email-related security incidents (per {Granularity}), split by severity, so you can see how resolution speed changes over time. Reference SLA targets: High 60, Medium 120, Low 240, Informational 480 minutes.**"},"name":"soc - time-to-close heading","id":"e23ccc6c-b0f0-407b-8e01-d8b69c40a745"},{"type":3,"content":{"version":"KqlItem/1.0","query":"// SLA thresholds by severity for email-security (MDO) incidents
let SLA_Variables = datatable (Severity:string, TimeToResolve:int) [
    "High", 60,
    "Medium", 120,
    "Low", 240,
    "Informational", 480
];

// Identify MDO-related incidents via alert correlation
let EmailSecurityIncidents = 
    SecurityIncident
    | mv-expand AlertIds
    | where isnotempty(AlertIds)
    | extend AlertId = tostring(AlertIds)
    | join kind=inner (
        SecurityAlert
        | where ProductName in ("Office 365 Advanced Threat Protection", "Microsoft 365 Defender")
        | extend AlertId = tostring(SystemAlertId)
        | project AlertId
    ) on AlertId
    | distinct ProviderIncidentId;

// Get latest incident state for each MDO-related incident
let LatestMdoIncidents =
    SecurityIncident
    | summarize arg_max(TimeGenerated, Classification, Status, Severity, CreatedTime, ClosedTime, Title) by ProviderIncidentId
    | where ProviderIncidentId in (EmailSecurityIncidents)
    | where not(Title startswith "CC_");  // Exclude non-email incidents as needed

LatestMdoIncidents
| where Status == "Closed"
| extend TimeToResolveIncident = datetime_diff('minute', ClosedTime, CreatedTime)
| join kind=inner SLA_Variables on Severity
| summarize
    ['Avg Time to Close (min)'] = avg(TimeToResolveIncident),
    CountIncidents = count(), Breached = countif(TimeToResolveIncident > TimeToResolve)
    by Day = bin(ClosedTime, 1d), Severity
| order by Day asc, Severity asc","size":0,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"linechart","chartSettings":{"xAxis":"Day","yAxis":["Avg Time to Close (min)"],"group":"Severity"}},"name":"soc - sla-by-severity trend","id":"3f7d1f17-8d2f-4a1b-a97e-17973812ca6f"},{"type":12,"content":{"version":"NotebookGroup/1.0","groupType":"editable","items":[{"type":1,"content":{"json":"### Closed Incident Classification (True Positive vs False Positive)

This visual shows the distribution of closed email-related incidents classified as True Positive versus False Positive. It helps assess detection accuracy and provides insight into validation trends."},"customWidth":"33.3","name":"soc - classification heading","styleSettings":{"margin":"10px"},"id":"48db10ce-8246-4f5e-8b68-f618d9c7f77c"},{"type":1,"content":{"json":"### True Positive Incident Classification Rate

This visual displays the percentage of email-related incidents confirmed as True Positive. It offers a clear measure of classification accuracy and highlights changes in detection effectiveness over time."},"customWidth":"33.3","name":"soc - tp-rate heading","styleSettings":{"margin":"10px"},"id":"34a84dbf-609a-407f-afef-f1592eb4a92b"},{"type":1,"content":{"json":"### Incidents Automated vs Manual Closure

This visual illustrates the proportion of email-related incidents closed automatically versus manually. It provides visibility into operational efficiency and the impact of automation on incident resolution.
<br> ⚠️ *You will have to review the underlying query and add any automation system specific to your organization.*"},"customWidth":"33.3","name":"soc - auto-vs-manual-closure heading","styleSettings":{"margin":"10px"},"id":"a1fd9136-7a12-4d80-b3e1-e2704a84f734"},{"type":3,"content":{"version":"KqlItem/1.0","query":"// Build a list of MDO-related incidents by cross-referencing SecurityAlert
let EmailSecurityIncidents = SecurityIncident
    | mv-expand AlertIds
    | where isnotempty(AlertIds)
    | extend AlertId = tostring(AlertIds)
    | join kind=inner (
        SecurityAlert
        | where ProductName in ("Office 365 Advanced Threat Protection", "Microsoft 365 Defender")
        | extend AlertId = tostring(SystemAlertId)
        | project AlertId
    ) on AlertId
    | distinct ProviderIncidentId;

// Get only the most recent state of each incident, ensuring it's MDO-related
let LatestIncidents = SecurityIncident
    | summarize arg_max(TimeGenerated, Classification, Status, Title) by ProviderIncidentId
    | where ProviderIncidentId in (EmailSecurityIncidents)
    | where not(Title startswith "CC_");  // Exclude incidents unrelated to MDO (e.g., DSPM)

LatestIncidents
| where Status == 'Closed'                                     // (Optional) Limit to closed/fully classified incidents
| summarize Count = count() by Classification = iif(
    isnull(Classification) or trim(" ", Classification) == "",
    "Not Set", 
    Classification
  )
| order by Count desc","size":3,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"piechart"},"customWidth":"33.3","name":"soc - classification pie","styleSettings":{"margin":"10px"},"id":"cfa5b7c5-50cc-4b3b-8bba-1a93c57bff43"},{"type":3,"content":{"version":"KqlItem/1.0","query":"// Identify MDO-related SecurityIncident IDs via alert correlation
let EmailSecurityIncidents = 
    SecurityIncident
    | mv-expand AlertIds
    | where isnotempty(AlertIds)
    | extend AlertId = tostring(AlertIds)
    | join kind=inner (
        SecurityAlert
        | where ProductName in ("Office 365 Advanced Threat Protection", "Microsoft 365 Defender")
        | extend AlertId = tostring(SystemAlertId)
        | project AlertId
    ) on AlertId
    | distinct ProviderIncidentId;

// Get latest incident state for MDO-related incidents
let LatestMdoIncidents =
    SecurityIncident
    | summarize arg_max(TimeGenerated, Classification, Status, IncidentName) by ProviderIncidentId
    | where ProviderIncidentId in (EmailSecurityIncidents)
    // Exclude other non-email incidents (e.g., DSPM with specific naming pattern)
    | where not(IncidentName startswith "CC_");

// Compute true positive rate among closed MDO incidents
LatestMdoIncidents
| where Status == "Closed"
| summarize
    TruePositiveCount = countif(Classification == "TruePositive"),
    TotalClosed       = count()
| extend TruePositiveRate = iff(
    TotalClosed > 0,
    TruePositiveCount * 100.0 / TotalClosed,
    real(null)
)","size":1,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"stat","statSettings":{"valueField":"TruePositiveRate","valueAggregation":"None","colorSettings":{"type":"static","mode":"background","heatmapPalette":"greenRed"},"numberFormatSettings":{"unit":1,"options":{"style":"decimal","maximumFractionDigits":2}},"tagText":"True Positive Rate","valueFontStyle":"xxLarge","tagTextPosition":"bottom"}},"customWidth":"33.3","name":"soc - tp-rate stat","styleSettings":{"margin":"10px"},"id":"eca235aa-38aa-46dd-a569-74dd8f83b2f0"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This queries shows the last activity on the Incident and attempts to display auto resolved incidents vs manual interaction.
//Add strings for your automations if you rely on any other application/system
//Fewer human-closed incidents (and a higher automated closure rate) generally indicates greater SecOps efficiency, as automation is successfully handling more work.

// Identify MDO-related incidents by joining SecurityIncident and SecurityAlert
let EmailSecurityIncidents = SecurityIncident
    | mv-expand AlertIds
    | where isnotempty(AlertIds)
    | extend AlertId = tostring(AlertIds)
    | join kind=inner (
        SecurityAlert
        | where ProductName in ("Office 365 Advanced Threat Protection", "Microsoft 365 Defender")
        | extend AlertId = tostring(SystemAlertId)
        | project AlertId
    ) on AlertId
    | distinct ProviderIncidentId;

// Get latest status of each incident and count closed incidents by who closed them
SecurityIncident
| summarize arg_max(TimeGenerated, *) by ProviderIncidentId
| where ProviderIncidentId in (EmailSecurityIncidents)
| where Status == 'Closed'
| where not(Title startswith "CC_")          // Exclude non-MDO incidents from DSPM policies
| extend ClosedBy = iff(                       // Add strings for your automation systems
        tolower(ModifiedBy) has_any ("system","azure","automation","playbook","microsoft xdr","microsoft defender xdr","created from alert"),
        "Automated",
        "Human"
    )
| summarize ClosedCount = count() by ClosedBy","size":3,"showAnalytics":true,"queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"piechart"},"customWidth":"33.3","name":"soc - closure pie","styleSettings":{"margin":"10px"},"id":"a4bc160f-1ba6-4779-86cd-ef44422f1e29"}]},"name":"soc - incident-insights group","id":"3083ac4d-0bdd-4db7-a5f0-0d41cb67a4eb"}]},"conditionalVisibility":{"parameterName":"Tab","comparison":"isEqualTo","value":"13"},"name":"soc - incident-metrics group","styleSettings":{"margin":"10px","padding":"10px","showBorder":true},"id":"18ff8970-e5f6-4c51-918a-aa693a45d18f"},{"type":12,"content":{"version":"NotebookGroup/1.0","groupType":"editable","items":[{"type":1,"content":{"json":"<table style="width:100%; border-collapse:collapse; border:none;background-color:#003366;">
<tr>
