**Remediation efficacy analysis.** Compares automated (AIR) and manual admin actions to evaluate response times and investigation outcomes.
<br><br>**Recommended action:** Reduce AIR pending-action latency by reviewing why approvals take long, and increase automation where it is safe to do so."},"name":"soc - air section header","id":"5e0b06c8-7774-4eb4-8b7f-572b3732de84"},{"type":1,"content":{"json":"### Automated Investigation and Response (AIR) Actions (per {Granularity})

This visual shows the per-{Granularity} trend of Automated Investigation and Response (AIR) actions, including the number of successful and failed attempts (because of prior remediation)."},"customWidth":"100","name":"soc - air-actions heading","styleSettings":{"margin":"10px"},"id":"05f14dec-e76c-413c-83a0-31a05dce65e7"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query attempts to show AIR Efficiency Over Time by displaying the number of successes and failures over time
EmailPostDeliveryEvents
| where ActionType =~ "Automated Remediation"
| extend Key = strcat(NetworkMessageId , '-', RecipientEmailAddress) 
| summarize arg_max(Timestamp, *) by Key
| summarize Count = count() by bin(Timestamp, {Granularity}), ActionResult","size":0,"showAnalytics":true,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"linechart","graphSettings":{"type":0,"topContent":{"columnMatch":"AlertId","formatter":1},"centerContent":{"columnMatch":"Count","formatter":1,"numberFormat":{"unit":17,"options":{"maximumSignificantDigits":3,"maximumFractionDigits":2}}}},"chartSettings":{"xAxis":"Timestamp"}},"customWidth":"100","name":"soc - air-efficiency trend","styleSettings":{"margin":"10px"},"id":"ae2a1850-5b7e-49f7-bac4-d888053ab49b"},{"type":1,"content":{"json":"### Automated Investigation and Response (AIR) Response Time After Email Delivery (per {Granularity})

This visual displays the average (per {Granularity}), 80th percentile (p80), 90th percentile (p90) and 99th percentile (p99) time needed, measured in minutes, from email delivery to AIR action. It serves as a SOC metric to monitor responsiveness (security team members reviewing and manually approving AIR Pending Actions) and identify potential latency in automated incident handling. If the latency is high focus on reviewing why reviwing AIR Pending Actions takes longer time for admins and consider <a href='https://learn.microsoft.com/en-us/defender-office-365/air-auto-remediation#configure-automated-remediation'>auto-aproval of URL, Files and Email clusters. </a>
"},"customWidth":"100","name":"soc - air-response-time heading","styleSettings":{"margin":"10px"},"id":"98c66d9e-efdf-40fc-b8b0-be35d7fd97a9"},{"type":3,"content":{"version":"KqlItem/1.0","query":"// SOC metric: Daily average/p75 delay (in minutes) from email delivery to AIR action
let deliveries = EmailEvents
  | where DeliveryAction == "Delivered"// delivered emails
  | extend MsgKey = strcat(NetworkMessageId, "-", RecipientEmailAddress)
  | summarize FirstDelivery = min(Timestamp) by MsgKey, Threat = tostring(ThreatTypes);
let remediations = EmailPostDeliveryEvents
  | where ActionType =~ "Automated Remediation"// automated remediation events
  | extend MsgKey = strcat(NetworkMessageId, "-", RecipientEmailAddress)
  | summarize FirstRemediation = min(Timestamp) by MsgKey;
deliveries
| join kind=inner remediations on MsgKey
| extend DelayMinutes = datetime_diff("minute", FirstRemediation, FirstDelivery)
| where DelayMinutes >= 0
| summarize ['Avg (min)'] = avg(DelayMinutes),
            ['P80 (min)'] = percentile(DelayMinutes, 80),
            ['P90 (min)'] = percentile(DelayMinutes, 90),
            ['P99 (min)'] = percentile(DelayMinutes, 99),
            CountEmails = count()
   by bin(FirstRemediation, 1d) ","size":0,"aggregation":3,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"areachart","gridSettings":{"sortBy":[{"itemKey":"FirstRemediation","sortOrder":1}]},"sortBy":[{"itemKey":"FirstRemediation","sortOrder":1}],"chartSettings":{"xAxis":"FirstRemediation","yAxis":["P99 (min)","P90 (min)","P80 (min)","Avg (min)"],"showLegend":true}},"customWidth":"100","name":"soc - air-latency area","styleSettings":{"margin":"10px"},"id":"900383f1-6443-4d50-b15d-26e4ac11b255"},{"type":1,"content":{"json":"### Automated Investigation and Response (AIR) Investigation Results Trend

This visual displays the per-{Granularity} trend of AIR investigation outcomes, categorized as **Threat Detected** or **Clean**. It helps track the effectiveness of automated investigations over time and highlights patterns in threat detection."},"customWidth":"67","name":"soc - air-outcomes heading","styleSettings":{"margin":"10px"},"id":"d1cabfbe-6040-4b6e-9ce5-f48e9973dfc9"},{"type":1,"content":{"json":"### Investigation Actions Taken: Automated Investigation and Response (AIR) vs Manual (Human)

This visual shows whether actions taken after an Automated Investigation and Response (AIR) required manual approval by an administrator or were executed automatically. It provides insight into the level of automation versus human intervention in post-investigation remediation."},"customWidth":"33","name":"soc - air-auto-vs-manual heading","styleSettings":{"margin":"10px"},"id":"2f98514b-0172-4c4e-ba25-9a5e4138c570"},{"type":3,"content":{"version":"KqlItem/1.0","query":"// AIR investigation outcomes by day: ThreatDetected vs. Clean

// Step 1: Deduplicate automated remediation events by message and recipient
let AutoRemediations = 
    EmailPostDeliveryEvents
    | where ActionType == "Automated Remediation"
    | summarize arg_max(Timestamp, ActionResult) by NetworkMessageId, RecipientEmailAddress
    | project NetworkMessageId, RecipientEmailAddress, Timestamp;

// Step 2: Derive threat verdicts using AlertEvidence
let EvidenceVerdicts =
    AlertEvidence
    | where EntityType in ("MailMessage", "MailCluster")
    | extend extra = todynamic(AdditionalFields)
    // If this is a mail cluster, use provided NetworkMessageIds array; otherwise wrap NetworkMessageId as a single-item array
    | extend networkIds = iff(
      isnull(extra.NetworkMessageIds) or array_length(extra.NetworkMessageIds) == 0,
      pack_array(NetworkMessageId),          // create a single-element array using pack_array
      extra.NetworkMessageIds                // use the array as-is if it exists
    )
    | mv-expand nmID = networkIds                // expand to individual message IDs
    // Derive verdict from LastVerdict, ThreatAnalysisSummary, and ThreatIntelligence
    | extend 
        lastVerdict = tolower(tostring(extra.LastVerdict)),
        threatAIList = extra.ThreatAnalysisSummary,
        threatInt   = extra.ThreatIntelligence
    | extend verdictFromAnalysis = iff(array_length(threatAIList) > 0, tolower(tostring(threatAIList[0].Verdict)), ""),
             verdictTI          = iff(array_length(threatInt) > 0, "malicious", "")   // any item in ThreatIntelligence indicates malicious
    // Mark as threat-detected if verdict is malicious/suspicious or threat evidence is present
    | extend ThreatDetectedFlag = 
        case(
            lastVerdict in ("malicious","suspicious") or verdictFromAnalysis in ("malicious","suspicious")
                or verdictTI == "malicious",
            true,
            false
        )
    // Weight mail clusters by MailCount; default to 1 for single messages
    | extend MailCountInt = toint(extra.MailCount)
    | extend Weight = iff(EntityType == "MailCluster", 
                        coalesce(MailCountInt, 1), // default to 1 if MailCount is missing
                        1)
    | summarize IsThreatDetected = any(ThreatDetectedFlag), 
                WeightSum       = sum(Weight) 
    by nmID = tostring(nmID);

// Step 3: Join remediation events with verdicts and aggregate by day
AutoRemediations
| join kind=leftouter EvidenceVerdicts on $left.NetworkMessageId == $right.nmID
| extend isThreat      = coalesce(IsThreatDetected, false), 
         effectiveWeight= coalesce(WeightSum, 1)
| extend InvestigationOutcome = iif(isThreat, "Threat Detected", "Clean")
| summarize PreventionCount = sum(effectiveWeight) by Day = bin(Timestamp, {Granularity}), InvestigationOutcome
| order by Day asc, InvestigationOutcome asc","size":0,"timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"linechart"},"customWidth":"67","name":"soc - air-outcomes trend","styleSettings":{"margin":"10px"},"id":"18552ccb-d8d4-45c4-a3cf-072203df9325"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query shows if the action taken after an Automated Investigation required manual approval by and admin or was automatically taken
EmailPostDeliveryEvents
| extend Key = strcat(NetworkMessageId , '-', RecipientEmailAddress) 
| summarize arg_max(Timestamp, *) by Key
| where ActionType == "Automated Remediation"
| summarize count() by ActionTrigger","size":3,"showAnalytics":true,"queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"visualization":"piechart"},"customWidth":"33","name":"soc - air-auto-vs-manual pie","styleSettings":{"margin":"10px","padding":"10px"},"id":"03bc6e3c-05de-426d-91d8-b48a36b4ea74"},{"type":12,"content":{"version":"NotebookGroup/1.0","groupType":"editable","items":[{"type":1,"content":{"json":"### Post-Delivery Actions by Admin

This visual displays the number (per {Granularity}) of emails where an administrator performed a post-delivery action. Actions are summarized by type, including **Soft Delete**, **Hard Delete**, **Moved to Junk Folder**, **Moved to Inbox**, and **Quarantine Release**, providing insight into manual intervention trends after email delivery."},"name":"soc - post-delivery-by-admin heading","styleSettings":{"margin":"10px"},"id":"a0961ca9-da58-49c4-9a1c-873c5569bed9"},{"type":3,"content":{"version":"KqlItem/1.0","query":"//This query visualises the daily ammount of emails that had an admin post delivery action, summarizing the data by action type
let gran = {Granularity};
let minTime = toscalar(EmailEvents | summarize min(Timestamp));
let maxTime = toscalar(EmailEvents | summarize max(Timestamp));
let agg = materialize(EmailPostDeliveryEvents
| where ActionTrigger has "AdminAction"
